export let s_instance: LAppWavFileHandler = null;
export class LAppWavFileHandler {
  public static getInstance(): LAppWavFileHandler {
    if (s_instance == null) {
      s_instance = new LAppWavFileHandler();
    }

    return s_instance;
  }

  public static releaseInstance(): void {
    if (s_instance != null) {
      s_instance = void 0;
    }

    s_instance = null;
  }

  public update(deltaTimeSeconds: number) {
    let goalOffset: number;
    let rms: number;

    if (
      this._pcmData == null ||
      this._sampleOffset >= this._wavFileInfo._samplesPerChannel
    ) {
      this._lastRms = 0.0;
      return false;
    }

    this._userTimeSeconds += deltaTimeSeconds;
    goalOffset = Math.floor(
      this._userTimeSeconds * this._wavFileInfo._samplingRate
    );

    if (goalOffset > this._wavFileInfo._samplesPerChannel) {
      goalOffset = this._wavFileInfo._samplesPerChannel;
    }

    rms = 0.0;

    for (
      let channelCount = 0;
      channelCount < this._wavFileInfo._numberOfChannels;
      channelCount++
    ) {
      for (
        let sampleCount = this._sampleOffset;
        sampleCount < goalOffset;
        sampleCount++
      ) {
        const pcm = this._pcmData[channelCount][sampleCount];
        rms += pcm * pcm;
      }
    }

    rms = Math.sqrt(
      rms /
        (this._wavFileInfo._numberOfChannels *
          (goalOffset - this._sampleOffset))
    );
    this._lastRms = rms;
    this._sampleOffset = goalOffset;
    return true;
  }

  public start(filePath: string): void {
    this._sampleOffset = 0;
    this._userTimeSeconds = 0.0;
    this._lastRms = 0.0;
    this.loadWavFile(filePath);
  }

  public getRms(): number {
    return this._lastRms;
  }

  public loadWavFile(filePath: string): Promise<boolean> {
    return fetch(filePath)
      .then(res => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.arrayBuffer();
      })
      .then(buf => {
        const success = this.loadWavFromArrayBuffer(buf, filePath);
        return success;
      })
      .catch(err => {
        console.error(`[WAV] Failed to load ${filePath}:`, err);
        return false;
      });
  }

  public startFromBuffer(
    arrayBuffer: ArrayBuffer,
    fileName: string = ''
  ): void {
    this._sampleOffset = 0;
    this._userTimeSeconds = 0.0;
    this._lastRms = 0.0;
    this.loadWavFromArrayBuffer(arrayBuffer, fileName);
  }

  public loadWavFromArrayBuffer(
    arrayBuffer: ArrayBuffer,
    fileName: string = ''
  ): boolean {
    if (this._pcmData != null) {
      this.releasePcmData();
    }

    this._byteReader._fileByte = arrayBuffer;
    this._byteReader._fileDataView = new DataView(arrayBuffer);
    this._byteReader._fileSize = arrayBuffer.byteLength;
    this._byteReader._readOffset = 0;
    this._wavFileInfo._fileName = fileName;

    if (this._byteReader._fileSize < 4) {
      console.error('[WAV] File too short');
      return false;
    }

    try {
      if (!this._byteReader.getCheckSignature('RIFF')) {
        console.error('[WAV] Missing RIFF signature');
        return false;
      }

      this._byteReader.get32LittleEndian();
      if (!this._byteReader.getCheckSignature('WAVE')) return false;
      if (!this._byteReader.getCheckSignature('fmt ')) return false;
      const fmtChunkSize = this._byteReader.get32LittleEndian();

      if (this._byteReader.get16LittleEndian() !== 1) {
        console.error('[WAV] Not linear PCM');
        return false;
      }

      this._wavFileInfo._numberOfChannels =
        this._byteReader.get16LittleEndian();
      this._wavFileInfo._samplingRate = this._byteReader.get32LittleEndian();
      this._byteReader.get32LittleEndian();
      this._byteReader.get16LittleEndian();
      this._wavFileInfo._bitsPerSample = this._byteReader.get16LittleEndian();

      if (fmtChunkSize > 16) {
        this._byteReader._readOffset += fmtChunkSize - 16;
      }

      while (this._byteReader._readOffset + 8 <= this._byteReader._fileSize) {
        const idBytes = new Uint8Array(4);

        for (let i = 0; i < 4; i++) {
          idBytes[i] = this._byteReader.get8();
        }

        const chunkId = new TextDecoder().decode(idBytes);
        const chunkSize = this._byteReader.get32LittleEndian();

        if (chunkId === 'data') {
          break;
        }

        const skip = (chunkSize + 1) & ~1;

        if (this._byteReader._readOffset + skip > this._byteReader._fileSize) {
          console.warn(`[WAV] Chunk ${chunkId} size too large`);
          break;
        }

        this._byteReader._readOffset += skip;
      }

      if (this._byteReader._readOffset >= this._byteReader._fileSize) {
        console.error('[WAV] Missing "data" chunk');
        return false;
      }

      if (this._byteReader._readOffset >= this._byteReader._fileSize) {
        console.error('[WAV] Missing data chunk');
        return false;
      }

      const dataChunkSize = this._byteReader.get32LittleEndian();
      this._wavFileInfo._samplesPerChannel =
        (dataChunkSize * 8) /
        (this._wavFileInfo._bitsPerSample *
          this._wavFileInfo._numberOfChannels);
      this._pcmData = new Array(this._wavFileInfo._numberOfChannels);

      for (let ch = 0; ch < this._wavFileInfo._numberOfChannels; ch++) {
        this._pcmData[ch] = new Float32Array(
          this._wavFileInfo._samplesPerChannel
        );
      }

      for (let s = 0; s < this._wavFileInfo._samplesPerChannel; s++) {
        for (let ch = 0; ch < this._wavFileInfo._numberOfChannels; ch++) {
          this._pcmData[ch][s] = this.getPcmSample();
        }
      }

      this._sampleOffset = 0;
      this._userTimeSeconds = 0.0;
      this._lastRms = 0.0;
      return true;
    } catch (e) {
      console.error('[WAV] Parse error:', e);
      return false;
    }
  }

  public getPcmSample(): number {
    let pcm32;

    switch (this._wavFileInfo._bitsPerSample) {
      case 8:
        pcm32 = this._byteReader.get8() - 128;
        pcm32 <<= 24;
        break;
      case 16:
        pcm32 = this._byteReader.get16LittleEndian() << 16;
        break;
      case 24:
        pcm32 = this._byteReader.get24LittleEndian() << 8;
        break;
      default:
        pcm32 = 0;
        break;
    }

    return pcm32 / 2147483647;
  }

  public getPcmDataChannel(usechannel: number): Float32Array {
    if (!this._pcmData || !(usechannel < this._pcmData.length)) {
      return null;
    }

    return Float32Array.from(this._pcmData[usechannel]);
  }

  public getWavSamplingRate(): number {
    if (!this._wavFileInfo || this._wavFileInfo._samplingRate < 1) {
      return null;
    }

    return this._wavFileInfo._samplingRate;
  }

  public releasePcmData(): void {
    for (
      let channelCount = 0;
      channelCount < this._wavFileInfo._numberOfChannels;
      channelCount++
    ) {
      this._pcmData[channelCount] = null;
    }

    delete this._pcmData;
    this._pcmData = null;
  }

  constructor() {
    this._pcmData = null;
    this._userTimeSeconds = 0.0;
    this._lastRms = 0.0;
    this._sampleOffset = 0.0;
    this._wavFileInfo = new WavFileInfo();
    this._byteReader = new ByteReader();
  }

  _pcmData: Array<Float32Array>;
  _userTimeSeconds: number;
  _lastRms: number;
  _sampleOffset: number;
  _wavFileInfo: WavFileInfo;
  _byteReader: ByteReader;
  loadFiletoBytes = (arrayBuffer: ArrayBuffer, length: number): void => {
    this._byteReader._fileByte = arrayBuffer;
    this._byteReader._fileDataView = new DataView(this._byteReader._fileByte);
    this._byteReader._fileSize = length;
  };
}
export class WavFileInfo {
  constructor() {
    this._fileName = '';
    this._numberOfChannels = 0;
    this._bitsPerSample = 0;
    this._samplingRate = 0;
    this._samplesPerChannel = 0;
  }

  _fileName: string;
  _numberOfChannels: number;
  _bitsPerSample: number;
  _samplingRate: number;
  _samplesPerChannel: number;
}
export class ByteReader {
  constructor() {
    this._fileByte = null;
    this._fileDataView = null;
    this._fileSize = 0;
    this._readOffset = 0;
  }

  public get8(): number {
    const ret = this._fileDataView.getUint8(this._readOffset);
    this._readOffset++;
    return ret;
  }

  public get16LittleEndian(): number {
    const ret =
      (this._fileDataView.getUint8(this._readOffset + 1) << 8) |
      this._fileDataView.getUint8(this._readOffset);
    this._readOffset += 2;
    return ret;
  }

  public get24LittleEndian(): number {
    const ret =
      (this._fileDataView.getUint8(this._readOffset + 2) << 16) |
      (this._fileDataView.getUint8(this._readOffset + 1) << 8) |
      this._fileDataView.getUint8(this._readOffset);
    this._readOffset += 3;
    return ret;
  }

  public get32LittleEndian(): number {
    const ret =
      (this._fileDataView.getUint8(this._readOffset + 3) << 24) |
      (this._fileDataView.getUint8(this._readOffset + 2) << 16) |
      (this._fileDataView.getUint8(this._readOffset + 1) << 8) |
      this._fileDataView.getUint8(this._readOffset);
    this._readOffset += 4;
    return ret;
  }

  public getCheckSignature(reference: string): boolean {
    const getSignature: Uint8Array = new Uint8Array(4);
    const referenceString: Uint8Array = new TextEncoder().encode(reference);

    if (reference.length != 4) {
      return false;
    }

    for (let signatureOffset = 0; signatureOffset < 4; signatureOffset++) {
      getSignature[signatureOffset] = this.get8();
    }

    return (
      getSignature[0] == referenceString[0] &&
      getSignature[1] == referenceString[1] &&
      getSignature[2] == referenceString[2] &&
      getSignature[3] == referenceString[3]
    );
  }

  _fileByte: ArrayBuffer;
  _fileDataView: DataView;
  _fileSize: number;
  _readOffset: number;
}
