import { CubismMatrix44 } from '@framework/math/cubismmatrix44';
import { ACubismMotion } from '@framework/motion/acubismmotion';
import { csmVector } from '@framework/type/csmvector';
import * as LAppDefine from '../core/define';
import { UpdateMotionListCallback } from '../core/define';
import { LAppModel } from '../assets/model';
import { LAppPal } from '../core/pal';
import { LAppSubdelegate } from '../delegation/subdelegate';
export class LAppLive2DManager {
  private releaseAllModel(): void {
    this._models.clear();
  }

  public onDrag(x: number, y: number): void {
    // Check if UI elements are being interacted with
    const isUIElementActive = (window as any).isUIElementActive;
    if (isUIElementActive) {
      return; // Don't process drag if UI is active
    }

    const model: LAppModel = this._models.at(0);

    if (model) {
      model.setDragging(x, y);
    }
  }

  public onTap(x: number, y: number): void {
    if (LAppDefine.DebugLogEnable) {
      LAppPal.printMessage(
        `[APP]tap point: {x: ${x.toFixed(2)} y: ${y.toFixed(2)}}`
      );
    }

    const model: LAppModel = this._models.at(0);

    if (model.hitTest(LAppDefine.HitAreaNameHead, x, y)) {
      if (LAppDefine.DebugLogEnable) {
        LAppPal.printMessage(`[APP]hit area: [${LAppDefine.HitAreaNameHead}]`);
      }

      model.startRandomMotion(
        LAppDefine.MotionGroupTapHead,
        LAppDefine.PriorityNormal,
        this.finishedMotion,
        this.beganMotion
      );
    } else if (model.hitTest(LAppDefine.HitAreaNameBody, x, y)) {
      if (LAppDefine.DebugLogEnable) {
        LAppPal.printMessage(`[APP]hit area: [${LAppDefine.HitAreaNameBody}]`);
      }

      model.startRandomMotion(
        LAppDefine.MotionGroupTapBody,
        LAppDefine.PriorityNormal,
        this.finishedMotion,
        this.beganMotion
      );
    }
  }

  public onUpdate(): void {
    const { width, height } = this._subdelegate.getCanvas();
    const projection: CubismMatrix44 = new CubismMatrix44();
    const model: LAppModel =
      this._models.getSize() > 0 ? this._models.at(0) : null;

    if (model && model.getModel()) {
      if (model.getModel().getCanvasWidth() > 1.0 && width < height) {
        model.getModelMatrix().setWidth(2.0);
        projection.scale(1.0, width / height);
      } else {
        projection.scale(height / width, 1.0);
      }

      if (this._viewMatrix != null) {
        projection.multiplyByMatrix(this._viewMatrix);
      }

      model.update();
      model.draw(projection);
    }
  }

  public nextScene(): void {
    if (this._models.getSize() > 0) {
      return;
    }
  }

  private changeScene(index: number): void {
    this._sceneIndex = index;

    if (LAppDefine.DebugLogEnable) {
      LAppPal.printMessage(`[APP]model index: ${this._sceneIndex}`);
    }

    console.log(`[LAppLive2DManager] changeScene called for index: ${index}`);
    const model: string = LAppDefine.ModelDir[index];
    const modelPath: string = LAppDefine.ResourcesPath + model + '/';
    let modelJsonName: string = LAppDefine.ModelDir[index];
    modelJsonName += '.model3.json';
    this.releaseAllModel();
    const instance = new LAppModel();

    if (this._updateMotionListCallback) {
      console.log(
        `[LAppLive2DManager] Setting updateMotionList callback for NEW model instance.`
      );
      instance.setOnModelLoadCompleteCallback(this._updateMotionListCallback);
    } else {
      console.warn(
        `[LAppLive2DManager] No updateMotionList callback found to set for NEW model instance.`
      );
      instance.setOnModelLoadCompleteCallback(null);
    }

    instance.setSubdelegate(this._subdelegate);
    console.log(
      `[LAppLive2DManager] Loading assets for new model: ${modelJsonName}`
    );
    instance.loadAssets(modelPath, modelJsonName);
    this._models.pushBack(instance);
  }

  public loadModelFromLocalFileMap(fileMap: Map<string, File>): void {
    this.releaseAllModel();
    const instance = new LAppModel();

    if (this._updateMotionListCallback) {
      console.log(
        `[LAppLive2DManager] Setting updateMotionList callback for NEW model instance (local map).`
      );
      instance.setOnModelLoadCompleteCallback(this._updateMotionListCallback);
    } else {
      instance.setOnModelLoadCompleteCallback(null);
    }

    instance.setSubdelegate(this._subdelegate);
    let modelJsonName: string | null = null;

    for (const key of fileMap.keys()) {
      if (key.endsWith('.model3.json')) {
        if (modelJsonName == null || key.length < modelJsonName.length) {
          modelJsonName = key.split('/').pop();
        }
      }
    }

    if (!modelJsonName) {
      console.error(
        '[LAppLive2DManager] No .model3.json found in provided file map.'
      );
      return;
    }

    instance.loadAssetsFromFileMap(fileMap, modelJsonName);
    this._models.pushBack(instance);
  }

  public setViewMatrix(m: CubismMatrix44) {
    for (let i = 0; i < 16; i++) {
      this._viewMatrix.getArray()[i] = m.getArray()[i];
    }
  }

  public addModel(sceneIndex: number = 0): void {
    this._sceneIndex = sceneIndex;
    this.changeScene(this._sceneIndex);
  }

  public constructor() {
    this._subdelegate = null;
    this._viewMatrix = new CubismMatrix44();
    this._models = new csmVector<LAppModel>();
    this._sceneIndex = 0;
  }

  public release(): void {}
  public initialize(subdelegate: LAppSubdelegate): void {
    this._subdelegate = subdelegate;
  }

  private _subdelegate: LAppSubdelegate;
  private _updateMotionListCallback: UpdateMotionListCallback | null = null;
  public setUpdateMotionListCallback(
    callback: UpdateMotionListCallback | null
  ): void {
    this._updateMotionListCallback = callback;
  }

  _viewMatrix: CubismMatrix44;
  _models: csmVector<LAppModel>;
  private _sceneIndex: number;
  beganMotion = (self: ACubismMotion): void => {
    LAppPal.printMessage('Motion Began:');
    console.log(self);
  };

  finishedMotion = (self: ACubismMotion): void => {
    LAppPal.printMessage('Motion Finished:');
    console.log(self);
  };

  public getCurrentModel(): LAppModel | null {
    if (this._sceneIndex >= 0 && this._sceneIndex < this._models.getSize()) {
      return this._models.at(this._sceneIndex);
    }

    if (this._models.getSize() > 0) {
      return this._models.at(0);
    }

    return null;
  }

  public getModelAt(index: number): LAppModel | null {
    if (index >= 0 && index < this._models.getSize()) {
      return this._models.at(index);
    }

    return null;
  }

  public getCurrentModelLoadedMotionNames(): string[] {
    const currentModel = this.getCurrentModel();

    if (currentModel) {
      return currentModel.getLoadedMotionNames();
    }

    return [];
  }

  public getCurrentModelLoadedExpressionNames(): string[] {
    const currentModel = this.getCurrentModel();

    if (currentModel) {
      return currentModel.getLoadedExpressionNames();
    }

    return [];
  }

  public getModelCount(): number {
    return this._models.getSize();
  }

  public getCurrentSceneIndex(): number {
    return this._sceneIndex;
  }

  private static sInstance: LAppLive2DManager = null;
  public static getInstance(): LAppLive2DManager {
    if (LAppLive2DManager.sInstance == null) {
      LAppLive2DManager.sInstance = new LAppLive2DManager();
    }

    return LAppLive2DManager.sInstance;
  }

  public static releaseInstance(): void {
    if (LAppLive2DManager.sInstance != null) {
      LAppLive2DManager.sInstance = null;
    }
  }
}
