import { CubismMatrix44 } from '@framework/math/cubismmatrix44';
import { CubismViewMatrix } from '@framework/math/cubismviewmatrix';
import * as LAppDefine from '../core/define';
import { LAppDelegate } from '../delegation/delegate';
import { LAppPal } from '../core/pal';
import { LAppSprite } from './sprite';
import { TextureInfo } from '../managers/texturemanager';
import { TouchManager } from '../managers/touchmanager';
import { LAppSubdelegate } from '../delegation/subdelegate';
export class LAppView {
  public constructor() {
    this._programId = null;
    this._back = null;
    this._gear = null;
    this._touchManager = new TouchManager();
    this._deviceToScreen = new CubismMatrix44();
    this._viewMatrix = new CubismViewMatrix();
    this._isPanning = false;
    this._panPointerId = -1;
    this._panLastX = 0;
    this._panLastY = 0;
    this._userModified = false; // true when user pans/zooms to avoid resets on resize
    this._initialViewScale = 1.0; // stored initial scale
    this._initialViewOffsetX = 0.0; // stored initial offset x
    this._initialViewOffsetY = 0.0; // stored initial offset y
  }

  public initialize(subdelegate: LAppSubdelegate): void {
    this._subdelegate = subdelegate;
    const { width, height } = subdelegate.getCanvas();
    const ratio: number = width / height;
    const left: number = -ratio;
    const right: number = ratio;
    const bottom: number = LAppDefine.ViewLogicalLeft;
    const top: number = LAppDefine.ViewLogicalRight;
    this._viewMatrix.setScreenRect(left, right, bottom, top);
    // Only set default scale if the user hasn't modified view (preserve user zoom/pan)
    if (!this._userModified) {
      // Use initial view scale from define
      this._viewMatrix.scale(LAppDefine.InitialViewScale, LAppDefine.InitialViewScale);

      // Store the initial view state values for later resets
      this._initialViewScale = LAppDefine.InitialViewScale;
      this._initialViewOffsetX = LAppDefine.InitialViewOffsetX;
      this._initialViewOffsetY = LAppDefine.InitialViewOffsetY;

      // Position view so canvas center maps to view origin, then apply initial offset
      const canvas = this._subdelegate.getCanvas();
      if (canvas) {
        const centerX = canvas.width * 0.5;
        const centerY = canvas.height * 0.5;
        const screenX = this._deviceToScreen.transformX(centerX);
        const screenY = this._deviceToScreen.transformY(centerY);
        // translate(x,y) sets the absolute translation values in the matrix
        const scale = this._initialViewScale || LAppDefine.ViewScale;
        this._viewMatrix.translate(screenX - this._initialViewOffsetX * scale, screenY - this._initialViewOffsetY * scale);
      }
    }
    this._deviceToScreen.loadIdentity();

    if (width > height) {
      const screenW: number = Math.abs(right - left);
      this._deviceToScreen.scaleRelative(screenW / width, -screenW / width);
    } else {
      const screenH: number = Math.abs(top - bottom);
      this._deviceToScreen.scaleRelative(screenH / height, -screenH / height);
    }

    this._deviceToScreen.translateRelative(-width * 0.5, -height * 0.5);
    this._viewMatrix.setMaxScale(LAppDefine.ViewMaxScale);
    this._viewMatrix.setMinScale(LAppDefine.ViewMinScale);
    this._viewMatrix.setMaxScreenRect(
      LAppDefine.ViewLogicalMaxLeft,
      LAppDefine.ViewLogicalMaxRight,
      LAppDefine.ViewLogicalMaxBottom,
      LAppDefine.ViewLogicalMaxTop
    );
  }

  public release(): void {
    this._viewMatrix = null;
    this._touchManager = null;
    this._deviceToScreen = null;

    if (this._gear) {
      this._gear.release();
      this._gear = null;
    }

    if (this._back) {
      this._back.release();
      this._back = null;
    }

    if (this._programId) {
      this._subdelegate.getGlManager().getGl().deleteProgram(this._programId);
      this._programId = null;
    }
  }

  public render(): void {
    this._subdelegate.getGlManager().getGl().useProgram(this._programId);

    if (this._back) {
      this._back.render(this._programId);
    }

    if (this._gear) {
      this._gear.render(this._programId);
    }

    this._subdelegate.getGlManager().getGl().flush();
    const lapplive2dmanager = this._subdelegate.getLive2DManager();

    if (lapplive2dmanager != null) {
      lapplive2dmanager.setViewMatrix(this._viewMatrix);
      lapplive2dmanager.onUpdate();
    }
  }

  // Start panning the view. deviceX / deviceY are canvas-local coordinates (pixels)
  public startPan(deviceX: number, deviceY: number, pointerId: number): void {
    this._isPanning = true;
    this._panPointerId = pointerId;
    this._panLastX = deviceX;
    this._panLastY = deviceY;
    this._userModified = true;
  }

  // Update panning movement.
  public movePan(deviceX: number, deviceY: number): void {
    if (!this._isPanning) return;
    const lastViewX = this.transformViewX(this._panLastX);
    const lastViewY = this.transformViewY(this._panLastY);
    const viewX = this.transformViewX(deviceX);
    const viewY = this.transformViewY(deviceY);
    const dx = viewX - lastViewX;
    const dy = viewY - lastViewY;
    // Translate relative so panning matches cursor movement
    this._viewMatrix.translateRelative(dx, dy);
    this._panLastX = deviceX;
    this._panLastY = deviceY;
  }

  // End panning.
  public endPan(): void {
    this._isPanning = false;
    this._panPointerId = -1;
  }

  public isPanning(): boolean {
    return this._isPanning;
  }

  public getPanPointerId(): number {
    return this._panPointerId;
  }

  public initializeSprite(): void {
    const width: number = this._subdelegate.getCanvas().width;
    const height: number = this._subdelegate.getCanvas().height;
    const textureManager = this._subdelegate.getTextureManager();
    const resourcesPath = LAppDefine.ResourcesPath;
    const imageName = '';

    const initBackGroundTexture = (textureInfo: TextureInfo): void => {
      const x: number = width * 0.5;
      const y: number = height * 0.5;
      const fwidth = textureInfo.width * 2.0;
      const fheight = height * 0.95;
      this._back = new LAppSprite(x, y, fwidth, fheight, textureInfo.id);
      this._back.setSubdelegate(this._subdelegate);
    };

    textureManager.createTextureFromPngFile(
      resourcesPath + imageName,
      false,
      initBackGroundTexture
    );

    const initGearTexture = (textureInfo: TextureInfo): void => {
      const x = width - textureInfo.width * 0.5;
      const y = height - textureInfo.height * 0.5;
      const fwidth = textureInfo.width;
      const fheight = textureInfo.height;
      this._gear = new LAppSprite(x, y, fwidth, fheight, textureInfo.id);
      this._gear.setSubdelegate(this._subdelegate);
    };

    textureManager.createTextureFromPngFile(
      resourcesPath + imageName,
      false,
      initGearTexture
    );

    if (this._programId == null) {
      this._programId = this._subdelegate.createShader();
    }
  }

  public onTouchesBegan(pointX: number, pointY: number): void {
    this._touchManager.touchesBegan(
      pointX * window.devicePixelRatio,
      pointY * window.devicePixelRatio
    );
  }

  public onTouchesMoved(pointX: number, pointY: number): void {
    if (this._isPanning) {
      // Ignore model drag while panning the view
      return;
    }
    const posX = pointX * window.devicePixelRatio;
    const posY = pointY * window.devicePixelRatio;
    const lapplive2dmanager = this._subdelegate.getLive2DManager();
    const viewX: number = this.transformViewX(this._touchManager.getX());
    const viewY: number = this.transformViewY(this._touchManager.getY());
    this._touchManager.touchesMoved(posX, posY);
    lapplive2dmanager.onDrag(viewX, viewY);
  }

  public onTouchesEnded(pointX: number, pointY: number): void {
    const posX = pointX * window.devicePixelRatio;
    const posY = pointY * window.devicePixelRatio;
    const lapplive2dmanager = this._subdelegate.getLive2DManager();
    lapplive2dmanager.onDrag(0.0, 0.0);
    const x: number = this.transformViewX(posX);
    const y: number = this.transformViewY(posY);

    if (LAppDefine.DebugTouchLogEnable) {
      LAppPal.printMessage(`[APP]touchesEnded x: ${x} y: ${y}`);
    }

    lapplive2dmanager.onTap(x, y);

    if (this._gear.isHit(posX, posY)) {
      lapplive2dmanager.nextScene();
    }
  }

  public transformViewX(deviceX: number): number {
    const screenX: number = this._deviceToScreen.transformX(deviceX);
    return this._viewMatrix.invertTransformX(screenX);
  }

  public transformViewY(deviceY: number): number {
    const screenY: number = this._deviceToScreen.transformY(deviceY);
    return this._viewMatrix.invertTransformY(screenY);
  }

  public transformScreenX(deviceX: number): number {
    return this._deviceToScreen.transformX(deviceX);
  }

  public transformScreenY(deviceY: number): number {
    return this._deviceToScreen.transformY(deviceY);
  }

  public onWheel(deltaY: number, deviceX?: number, deviceY?: number): void {
    // Zoom amount: scale is 1 for no change, <1 to zoom out, >1 to zoom in
    // Use deltaY to compute a smooth multiplier. Positive deltaY zooms out.
    const angleDelta = deltaY;
    // Reduce sensitivity: use an exponential decay factor with small multiplier
    const k = 0.002; // smaller -> smoother
    const zoomFactor = Math.exp(-angleDelta * k);

    const oldScaleX = this._viewMatrix.getScaleX();
    const targetScale = oldScaleX * zoomFactor;
    // Clamp to min/max via adjusting factor
    const clampedScale = Math.min(
      LAppDefine.ViewMaxScale,
      Math.max(LAppDefine.ViewMinScale, targetScale)
    );
    const actualFactor = clampedScale / oldScaleX;

    // Use screen coords for adjustScale - compute from device coords
    let screenX: number;
    let screenY: number;
    if (deviceX !== undefined && deviceY !== undefined) {
      screenX = this._deviceToScreen.transformX(deviceX);
      screenY = this._deviceToScreen.transformY(deviceY);
    } else {
      // Default to canvas center
      const canvas = this._subdelegate.getCanvas();
      const centerX = canvas.width * 0.5;
      const centerY = canvas.height * 0.5;
      screenX = this._deviceToScreen.transformX(centerX);
      screenY = this._deviceToScreen.transformY(centerY);
    }

    // Use the provided adjustScale API which handles translations and clamping
    (this._viewMatrix as any).adjustScale(screenX, screenY, actualFactor);
    this._userModified = true;
  }

  public zoomByFactor(factor: number, deviceX?: number, deviceY?: number): void {
    let screenX: number;
    let screenY: number;
    if (deviceX !== undefined && deviceY !== undefined) {
      screenX = this._deviceToScreen.transformX(deviceX);
      screenY = this._deviceToScreen.transformY(deviceY);
    } else {
      const canvas = this._subdelegate.getCanvas();
      const centerX = canvas.width * 0.5;
      const centerY = canvas.height * 0.5;
      screenX = this._deviceToScreen.transformX(centerX);
      screenY = this._deviceToScreen.transformY(centerY);
    }

    (this._viewMatrix as any).adjustScale(screenX, screenY, factor);
    this._userModified = true;
  }

  public resetView(): void {
    const canvas = this._subdelegate.getCanvas();
    if (!canvas) return;
    const ratio: number = canvas.width / canvas.height;
    const left: number = -ratio;
    const right: number = ratio;
    const bottom: number = LAppDefine.ViewLogicalLeft;
    const top: number = LAppDefine.ViewLogicalRight;
    this._viewMatrix.setScreenRect(left, right, bottom, top);
    // Use the initial scale captured at initialize; fallback to default ViewScale
    const scaleToUse = this._initialViewScale || LAppDefine.ViewScale;
    this._viewMatrix.scale(scaleToUse, scaleToUse);
    this._viewMatrix.setMaxScale(LAppDefine.ViewMaxScale);
    this._viewMatrix.setMinScale(LAppDefine.ViewMinScale);
    this._viewMatrix.setMaxScreenRect(
      LAppDefine.ViewLogicalMaxLeft,
      LAppDefine.ViewLogicalMaxRight,
      LAppDefine.ViewLogicalMaxBottom,
      LAppDefine.ViewLogicalMaxTop
    );
    // Reset translation so the canvas center maps to view center (add optional offset)
    if (canvas) {
      const centerX = canvas.width * 0.5;
      const centerY = canvas.height * 0.5;
      const screenX = this._deviceToScreen.transformX(centerX);
      const screenY = this._deviceToScreen.transformY(centerY);
      const scale = this._initialViewScale || LAppDefine.ViewScale;
      // To set the view origin to the (initial) offset, compute absolute translation:
      // translateX = screenX - offsetX * scale
      this._viewMatrix.translate(screenX - this._initialViewOffsetX * scale, screenY - this._initialViewOffsetY * scale);
    }
    this._userModified = false;
  }

  // Capture the current view matrix, scale, and offsets to be used as the "initial" state.
  // This allows us to call this after a model finishes loading so the reset button restores
  // the view that the app had at that moment.
  public captureInitialViewState(): void {
    const canvas = this._subdelegate?.getCanvas();
    if (!canvas) return;
    const centerX = canvas.width * 0.5;
    const centerY = canvas.height * 0.5;
    const screenX = this._deviceToScreen.transformX(centerX);
    const screenY = this._deviceToScreen.transformY(centerY);
    const tx = this._viewMatrix.getTranslateX();
    const ty = this._viewMatrix.getTranslateY();
    const scale = this._viewMatrix.getScaleX() || LAppDefine.ViewScale;

    this._initialViewScale = scale;
    // Convert translate values back into the offset form used elsewhere:
    // offset = (screen - translate) / scale
    this._initialViewOffsetX = (screenX - tx) / scale;
    this._initialViewOffsetY = (screenY - ty) / scale;
  }

  _touchManager: TouchManager;
  _deviceToScreen: CubismMatrix44;
  _viewMatrix: CubismViewMatrix;
  _programId: WebGLProgram;
  _back: LAppSprite;
  _gear: LAppSprite;
  _changeModel: boolean;
  _isClick: boolean;
  private _subdelegate: LAppSubdelegate;
  _isPanning: boolean;
  _panPointerId: number;
  _panLastX: number;
  _panLastY: number;
  _userModified: boolean;
  _initialViewScale: number;
  _initialViewOffsetX: number;
  _initialViewOffsetY: number;
}
