import { LAppDelegate } from './delegation/delegate';
import * as LAppDefine from './core/define';
import { CubismFramework } from '@framework/live2dcubismframework';

// Track if UI elements are being interacted with
let isUIElementActive = false;

function setUIElementActive(active: boolean): void {
  isUIElementActive = active;
  (window as any).isUIElementActive = active; // Expose to window for other modules
}

function getFocusableElements(container: HTMLElement): HTMLElement[] {
  const selectors = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';
  return Array.from(container.querySelectorAll(selectors)) as HTMLElement[];
}

function focusRelative(container: HTMLElement, current: HTMLElement | null, direction: 'next' | 'prev'): void {
  const elements = getFocusableElements(container).filter(e => !e.hasAttribute('disabled'));
  if (elements.length === 0) return;
  let index = current ? elements.indexOf(current) : -1;
  if (direction === 'next') {
    index = (index + 1) % elements.length;
  } else {
    index = (index - 1 + elements.length) % elements.length;
  }
  elements[index].focus();
}

function setupMotionListUI(): void {
  const toggleBtn = document.getElementById('toggle-window-btn') as HTMLButtonElement;
  const windowDiv = document.getElementById('motion-list-window') as HTMLDivElement;
  const listUl = document.getElementById('motion-list') as HTMLUListElement;
  const multiSelect = document.getElementById('motion-multi-select') as HTMLSelectElement;
  const mergeBtn = document.getElementById('merge-btn') as HTMLButtonElement;

  // Accessibility attributes
  if (toggleBtn) toggleBtn.setAttribute('aria-controls', 'motion-list-window');
  if (toggleBtn) toggleBtn.setAttribute('aria-expanded', 'false');
  if (windowDiv) windowDiv.setAttribute('role', 'dialog');
  if (windowDiv) windowDiv.setAttribute('aria-hidden', 'true');
  if (windowDiv) windowDiv.setAttribute('tabindex', '0');

  // Keyboard navigation for the motion window
  if (windowDiv) {
    windowDiv.addEventListener('keydown', (e) => {
      const active = document.activeElement as HTMLElement | null;
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        focusRelative(windowDiv, active, 'next');
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        focusRelative(windowDiv, active, 'prev');
      } else if (e.key === 'Enter') {
        if (active && active.tagName === 'BUTTON') {
          (active as HTMLButtonElement).click();
        }
      }
    });
  }

  if (!toggleBtn || !windowDiv || !listUl || !multiSelect || !mergeBtn) {
    console.error('Motion List UI elements not found in HTML.');
    return;
  }

  let isWindowVisible = false;
  toggleBtn.addEventListener('click', () => {
    isWindowVisible = !isWindowVisible;
    windowDiv.style.display = isWindowVisible ? 'block' : 'none';
    toggleBtn.setAttribute('aria-expanded', String(isWindowVisible));
    windowDiv.setAttribute('aria-hidden', String(!isWindowVisible));
    updateMotionList();
    // Reposition any docked windows when the motion panel toggles
    updateDockedWindowsPositions();
    if (isWindowVisible) {
      // focus the multi-select if present, otherwise first motion button
      const focusTarget = multiSelect ?? (listUl.querySelector('button') as HTMLElement | null);
      if (focusTarget) focusTarget.focus();
    } else {
      toggleBtn.focus();
    }
  });

  // Also allow toggling via keyboard from the toggle button (space/enter handled by button)
  // Ensure initial positioning at load
  updateDockedWindowsPositions();
  // Ensure merge button is disabled until there are at least two selected items
  mergeBtn.disabled = true;
  mergeBtn.title = 'Select two or more motions to enable merging';
  mergeBtn.addEventListener('click', async () => {
    console.log('[MotionListUI] Merge button clicked.');
    const appDelegate = LAppDelegate.getInstance();
    const subdelegates = appDelegate.getSubdelegates();

    if (!subdelegates || subdelegates.getSize() === 0) {
      console.error('[MotionListUI] No subdelegates found for merge.');
      return;
    }

    const firstSubdelegate = subdelegates.at(0);

    if (!firstSubdelegate) {
      console.error('[MotionListUI] No first subdelegate found for merge.');
      return;
    }

    const live2DManager = firstSubdelegate.getLive2DManager();

    if (!live2DManager) {
      console.error(
        '[MotionListUI] No Live2DManager found in subdelegate for merge.'
      );
      return;
    }

    const currentModel = live2DManager.getCurrentModel();

    if (!currentModel) {
      console.error(
        '[MotionListUI] No current model found in manager for merge.'
      );
      return;
    }

    const selectedNames: string[] = [];

    for (let i = 0; i < multiSelect.options.length; i++) {
      if (multiSelect.options[i].selected) {
        selectedNames.push(multiSelect.options[i].value);
      }
    }

    if (selectedNames.length < 2) {
      console.warn(
        '[MotionListUI] Please select at least two motions to merge.'
      );
      alert('Please select at least two motions to merge.');
      return;
    }

    console.log(
      `[MotionListUI] Attempting to merge motions: ${selectedNames.join(', ')}`
    );

    try {
      const success = await currentModel.startMergedMotionFromNamesArray(
        selectedNames,
        LAppDefine.PriorityForce
      );

      if (success) {
        console.log('[MotionListUI] Merged motion started successfully.');
      } else {
        console.error('[MotionListUI] Failed to start merged motion.');
        alert('Failed to start merged motion. Check console for details.');
      }
    } catch (error) {
      console.error('[MotionListUI] Error during merge process:', error);
      alert(
        'An error occurred during the merge process. Check console for details.'
      );
    }
  });

  // Enable/disable merge button when selection changes and show count
  multiSelect.addEventListener('change', () => {
    const selectedCount = Array.from(multiSelect.options).filter(o => o.selected).length;
    mergeBtn.disabled = selectedCount < 2;
    mergeBtn.textContent = selectedCount > 0 ? `Merge & Play (${selectedCount})` : 'Merge & Play';
  });

  // Update merge button state initially (for when updateMotionList populates the list)
  mergeBtn.textContent = 'Merge & Play';

  function updateMotionList(): void {
    console.log('[MotionListUI] updateMotionList called via callback.');
    listUl.innerHTML = '';
    multiSelect.innerHTML = '';
    const appDelegate = LAppDelegate.getInstance();
    const subdelegates = appDelegate.getSubdelegates();

    if (!subdelegates || subdelegates.getSize() === 0) {
      console.error('[MotionListUI] No subdelegates found in appDelegate.');
      const listItem = document.createElement('li');
      const span = document.createElement('span');
      span.textContent = 'No subdelegates found';
      listItem.appendChild(span);
      listUl.appendChild(listItem);
      return;
    }

    const firstSubdelegate = subdelegates.at(0);

    if (!firstSubdelegate) {
      console.error('[MotionListUI] No first subdelegate found.');
      const listItem = document.createElement('li');
      const span = document.createElement('span');
      span.textContent = 'No first subdelegate found';
      listItem.appendChild(span);
      listUl.appendChild(listItem);
      return;
    }

    const live2DManager = firstSubdelegate.getLive2DManager();

    if (!live2DManager) {
      console.error('[MotionListUI] No Live2DManager found in subdelegate.');
      const listItem = document.createElement('li');
      const span = document.createElement('span');
      span.textContent = 'No Live2DManager found in subdelegate';
      listItem.appendChild(span);
      listUl.appendChild(listItem);
      return;
    }

    const currentModel = live2DManager.getCurrentModel();
    console.log('[MotionListUI] Current model in callback:', currentModel);

    if (currentModel) {
      console.log(
        '[MotionListUI] Found current model, attempting to get motion names...'
      );
      const motionNames = live2DManager.getCurrentModelLoadedMotionNames();
      console.log(
        `[MotionListUI] Retrieved ${motionNames.length} motion names in callback:`,
        motionNames
      );

      if (motionNames.length === 0) {
        const listItem = document.createElement('li');
        const span = document.createElement('span');
        span.textContent = 'Motions not loaded yet or empty (in callback)';
        listItem.appendChild(span);
        listUl.appendChild(listItem);
        console.warn('[MotionListUI] Motion names array is empty in callback.');
        return;
      }

      motionNames.forEach((name: string) => {
        const option = document.createElement('option');
        option.value = name;
        option.textContent = name;
        multiSelect.appendChild(option);
      });

      // If there are fewer than 2 choices, disable merge button and clear label
      mergeBtn.disabled = motionNames.length < 2;
      mergeBtn.textContent = 'Merge & Play';
      if (motionNames.length < 2) mergeBtn.title = 'Select two or more motions to enable merging';
      else mergeBtn.title = '';
      motionNames.forEach((name: string) => {
        const listItem = document.createElement('li');
        const button = document.createElement('button');
        button.className = 'motion-btn';
        button.textContent = name;
        console.log(
          `[MotionListUI] Adding button for motion: ${name} (in callback)`
        );
        button.addEventListener('click', () => {
          console.log(
            `[MotionListUI] Triggering motion: ${name} (in callback)`
          );
          // Reposition after content size changes
          updateDockedWindowsPositions();


          const lastUnderscore = name.lastIndexOf('_');
          if (lastUnderscore !== -1) {
            const group = name.substring(0, lastUnderscore);
            const no = parseInt(name.substring(lastUnderscore + 1));


            currentModel.startMotion(group, no, LAppDefine.PriorityForce);
          } else {
            console.warn(`[MotionListUI] Could not parse motion name: ${name}`);

            currentModel.startMotionByName(name, LAppDefine.PriorityForce);
          }
        });
        listItem.appendChild(button);
        listUl.appendChild(listItem);
      });
      console.log(
        '[MotionListUI] Finished adding buttons to list in callback.'
      );
      // Capture the view's current transform/scale as the initial state (so Reset returns here)
      try {
        const view = firstSubdelegate.getView();
        if (view && (view as any).captureInitialViewState) {
          (view as any).captureInitialViewState();
        }
      } catch (e) {
        console.warn('[MotionListUI] Failed to capture initial view state', e);
      }
      // If expression UI exists, update its list as well
      if ((window as any).updateExpressionList) (window as any).updateExpressionList();
      if ((window as any).updateParameterList) (window as any).updateParameterList();
      updateDockedWindowsPositions();
    } else {
      console.warn(
        '[MotionListUI] No current model found in manager (in callback).'
      );
      const listItem = document.createElement('li');
      const span = document.createElement('span');
      span.textContent = 'No model loaded (in callback)';
      listItem.appendChild(span);
      listUl.appendChild(listItem);
    }
  }

  const appDelegate = LAppDelegate.getInstance();
  appDelegate.setUpdateMotionListCallback(updateMotionList);
}



function setupParameterUI(): void {
  const toggleBtn = document.getElementById(
    'toggle-params-btn'
  ) as HTMLButtonElement;
  const windowDiv = document.getElementById(
    'parameter-window'
  ) as HTMLDivElement;
  const parameterList = document.getElementById('parameter-list') as HTMLDivElement;

  if (!toggleBtn || !windowDiv || !parameterList) {
    console.error('Parameter UI elements not found in HTML.');
    return;
  }

  let isWindowVisible = false;
  let updateInterval: number | null = null;

  // Accessibility attributes
  toggleBtn.setAttribute('aria-controls', 'parameter-window');
  toggleBtn.setAttribute('aria-expanded', 'false');
  windowDiv.setAttribute('role', 'dialog');
  windowDiv.setAttribute('aria-hidden', 'true');
  windowDiv.setAttribute('tabindex', '0');

  toggleBtn.addEventListener('click', () => {
    isWindowVisible = !isWindowVisible;
    windowDiv.style.display = isWindowVisible ? 'block' : 'none';
    toggleBtn.setAttribute('aria-expanded', String(isWindowVisible));
    windowDiv.setAttribute('aria-hidden', String(!isWindowVisible));
    if (isWindowVisible) {
      console.log('[ParameterUI] Window opened, updating parameter list...');
      updateParameterList();
      // Start updating parameter values in real-time
      if (updateInterval) clearInterval(updateInterval);
      updateInterval = window.setInterval(updateParameterValues, 100);

      // Focus first slider or refresh button
      const focusTarget = parameterList.querySelector('input, button') as HTMLElement | null;
      if (focusTarget) focusTarget.focus();

      // *** REMOVED: No longer need drag enable/disable logic ***
    } else {
      // Stop updating when window is closed
      if (updateInterval) {
        clearInterval(updateInterval);
        updateInterval = null;
      }

      // *** REMOVED: No longer need drag enable/disable logic ***
      toggleBtn.focus();
    }
  });

  // Store slider elements for real-time updates AND their corresponding IDs + default values
  const sliderElements = new Map<number, {
    slider: HTMLInputElement,
    display: HTMLSpanElement,
    paramId: string, // Store the parameter ID string
    defaultValue: number
  }>();

  function updateParameterValues(): void {
    const appDelegate = LAppDelegate.getInstance();
    const subdelegates = appDelegate.getSubdelegates();
    if (!subdelegates || subdelegates.getSize() === 0) return;

    const firstSubdelegate = subdelegates.at(0);
    if (!firstSubdelegate) return;

    const live2DManager = firstSubdelegate.getLive2DManager();
    if (!live2DManager) return;

    const currentModel = live2DManager.getCurrentModel();
    if (!currentModel) return;

    // Access the underlying CubismModel through the framework methods
    const model = currentModel.getModel(); // This returns the CubismModel instance
    if (!model) return;

    sliderElements.forEach((elements, paramIndex) => {
      try {
        // Read the current value from the CubismModel state
        const currentValue = model.getParameterValueByIndex(paramIndex);
        // Only update UI if not currently being dragged by user
        if (document.activeElement !== elements.slider) {
          elements.slider.value = currentValue.toString();
          elements.display.textContent = currentValue.toFixed(2);
        }
      } catch (e) {
        console.warn(`[ParameterUI] Could not read parameter ${paramIndex} (${elements.paramId}):`, e);
      }
    });
  }

  function updateParameterList(): void {
    console.log('[ParameterUI] updateParameterList called.');
    parameterList.innerHTML = '';
    sliderElements.clear(); // Clear old references

    const appDelegate = LAppDelegate.getInstance();
    const subdelegates = appDelegate.getSubdelegates();

    if (!subdelegates || subdelegates.getSize() === 0) {
      console.error('[ParameterUI] No subdelegates found.');
      const messageDiv = document.createElement('div');
      messageDiv.textContent = 'No model loaded';
      messageDiv.style.color = '#aaa';
      messageDiv.style.textAlign = 'center';
      messageDiv.style.padding = '20px';
      parameterList.appendChild(messageDiv);
      return;
    }

    const firstSubdelegate = subdelegates.at(0);
    if (!firstSubdelegate) {
      console.error('[ParameterUI] No first subdelegate found.');
      const messageDiv = document.createElement('div');
      messageDiv.textContent = 'No model loaded';
      messageDiv.style.color = '#aaa';
      messageDiv.style.textAlign = 'center';
      messageDiv.style.padding = '20px';
      parameterList.appendChild(messageDiv);
      return;
    }

    const live2DManager = firstSubdelegate.getLive2DManager();
    if (!live2DManager) {
      console.error('[ParameterUI] No Live2DManager found.');
      const messageDiv = document.createElement('div');
      messageDiv.textContent = 'No model loaded';
      messageDiv.style.color = '#aaa';
      messageDiv.style.textAlign = 'center';
      messageDiv.style.padding = '20px';
      parameterList.appendChild(messageDiv);
      return;
    }

    const currentModel = live2DManager.getCurrentModel();
    if (!currentModel) {
      console.warn('[ParameterUI] No current model found.');
      const messageDiv = document.createElement('div');
      messageDiv.textContent = 'No model loaded';
      messageDiv.style.color = '#aaa';
      messageDiv.style.textAlign = 'center';
      messageDiv.style.padding = '20px';
      parameterList.appendChild(messageDiv);
      return;
    }

    const model = currentModel.getModel(); // Use the public method from CubismUserModel
    if (!model) {
      console.error('[ParameterUI] Model not accessible via getModel().');
      const messageDiv = document.createElement('div');
      messageDiv.textContent = 'Model not accessible';
      messageDiv.style.color = '#aaa';
      messageDiv.style.textAlign = 'center';
      messageDiv.style.padding = '20px';
      parameterList.appendChild(messageDiv);
      return;
    }

    if (typeof model.getParameterCount !== 'function') {
      console.error('[ParameterUI] getParameterCount method not found on model.');
      const messageDiv = document.createElement('div');
      messageDiv.textContent = 'Parameter interface not available';
      messageDiv.style.color = '#aaa';
      messageDiv.style.textAlign = 'center';
      messageDiv.style.padding = '20px';
      parameterList.appendChild(messageDiv);
      return;
    }

    const parameterCount = model.getParameterCount();
    console.log(`[ParameterUI] Found ${parameterCount} parameters.`);

    if (parameterCount === 0) {
      const messageDiv = document.createElement('div');
      messageDiv.textContent = 'No parameters found';
      messageDiv.style.color = '#aaa';
      messageDiv.style.textAlign = 'center';
      messageDiv.style.padding = '20px';
      parameterList.appendChild(messageDiv);
      return;
    }

    for (let i = 0; i < parameterCount; i++) {
      const parameterIndex = i;
      const parameterIdObj = model.getParameterId(parameterIndex);
      const parameterId =
        (parameterIdObj?.getString?.().s as string | undefined) ??
        (parameterIdObj as unknown as string) ??
        `Param_${parameterIndex}`;

      let parameterValue;
      try {
        parameterValue = model.getParameterValueByIndex(parameterIndex);
      } catch (e) {
        console.warn(`[ParameterUI] Could not get value for parameter ${parameterId}, using default`);
        parameterValue = model.getParameterDefaultValue(parameterIndex) || 0;
      }

      const parameterMin = model.getParameterMinimumValue(parameterIndex) || 0;
      const parameterMax = model.getParameterMaximumValue(parameterIndex) || 1;
      const parameterDefault = model.getParameterDefaultValue(parameterIndex) || 0;

      console.log(`[ParameterUI] Parameter ${parameterId} (index ${parameterIndex}): value=${parameterValue}, min=${parameterMin}, max=${parameterMax}, default=${parameterDefault}`);

      const parameterItem = document.createElement('div');
      parameterItem.className = 'parameter-item';

      const label = document.createElement('label');
      label.className = 'parameter-label';
      label.textContent = `${parameterId} [${parameterIndex}]`;
      parameterItem.appendChild(label);

      const sliderContainer = document.createElement('div');
      sliderContainer.style.display = 'flex';
      sliderContainer.style.alignItems = 'center';

      const slider = document.createElement('input');
      slider.type = 'range';
      slider.className = 'parameter-slider';
      slider.min = parameterMin.toString();
      slider.max = parameterMax.toString();
      slider.step = '0.01';
      slider.value = parameterValue.toString();

      const valueDisplay = document.createElement('span');
      valueDisplay.className = 'parameter-value';
      valueDisplay.textContent = parameterValue.toFixed(2);

      // Store slider, display, parameter ID string and default value
      sliderElements.set(parameterIndex, { slider, display: valueDisplay, paramId: parameterId, defaultValue: parameterDefault });

      // Prevent model dragging when slider is being interacted with
      slider.addEventListener('mousedown', () => {
        setUIElementActive(true);
      });
      slider.addEventListener('mouseup', () => {
        setUIElementActive(false);
      });
      slider.addEventListener('touchstart', () => {
        setUIElementActive(true);
      });
      slider.addEventListener('touchend', () => {
        setUIElementActive(false);
      });

      // --- CHANGE: Queue the parameter change instead of applying it directly ---
      slider.addEventListener('input', (e) => { // Keep 'input' for responsiveness
        const value = parseFloat((e.target as HTMLInputElement).value);
        valueDisplay.textContent = value.toFixed(2);

        // Use the new queue method on the currentModel instance
        try {
          if (typeof (currentModel as any).queueParameterChange === 'function') {
            (currentModel as any).queueParameterChange(parameterId, value); // Pass ID string and value
            console.log(`[ParameterUI] Queued parameter ${parameterId} (index ${parameterIndex}) to ${value} via queueParameterChange`);
          } else {
            console.error(`[ParameterUI] queueParameterChange method not found on model.`);
          }
        } catch (error) {
          console.error(`[ParameterUI] Error queueing parameter ${parameterId} (index ${parameterIndex}) to ${value}:`, error);
        }
      });

      const resetBtn = document.createElement('button');
      resetBtn.textContent = 'Reset';
      resetBtn.style.marginLeft = '10px';
      resetBtn.style.padding = '2px 8px';
      resetBtn.style.fontSize = '0.8em';
      resetBtn.style.backgroundColor = '#666';
      resetBtn.style.color = 'white';
      resetBtn.style.border = '1px solid #888';
      resetBtn.style.borderRadius = '3px';
      resetBtn.style.cursor = 'pointer';

      resetBtn.addEventListener('click', () => {
        // Clear the parameter override so it goes back to automatic control
        try {
          if (typeof (currentModel as any).clearParameterOverride === 'function') {
            (currentModel as any).clearParameterOverride(parameterId);
            console.log(`[ParameterUI] Cleared parameter override for ${parameterId}`);
            // Reset slider UI to show default value
            slider.value = parameterDefault.toString();
            valueDisplay.textContent = parameterDefault.toFixed(2);
          } else {
            console.error(`[ParameterUI] clearParameterOverride method not found on model.`);
          }
        } catch (error) {
          console.error(`[ParameterUI] Error clearing parameter override for ${parameterId}:`, error);
        }
      });

      sliderContainer.appendChild(slider);
      sliderContainer.appendChild(valueDisplay);
      sliderContainer.appendChild(resetBtn);
      parameterItem.appendChild(sliderContainer);
      parameterList.appendChild(parameterItem);
    }

    console.log('[ParameterUI] Finished creating parameter sliders.');

    // Create or re-use a controls container in the parameter window
    const existingControls = windowDiv.querySelector('.window-controls') as HTMLDivElement | null;
    let controlsContainer: HTMLDivElement;
    if (existingControls) {
      controlsContainer = existingControls;
      controlsContainer.innerHTML = '';
    } else {
      controlsContainer = document.createElement('div');
      controlsContainer.className = 'window-controls';
    }

    const refreshBtn = document.createElement('button');
    refreshBtn.textContent = 'Refresh Parameters';
    refreshBtn.className = 'refresh-btn';

    refreshBtn.addEventListener('click', () => {
      console.log('[ParameterUI] Manual refresh triggered');
      updateParameterList();
    });

    const resetAllBtn = document.createElement('button');
    resetAllBtn.textContent = 'Reset All';
    resetAllBtn.className = 'refresh-btn';

    resetAllBtn.addEventListener('click', () => {
      try {
        // Get current model reference
        const appDelegate = LAppDelegate.getInstance();
        const subs = appDelegate.getSubdelegates();
        if (!subs || subs.getSize() === 0) {
          console.error('[ParameterUI] No subdelegates found for reset');
          return;
        }
        const sub = subs.at(0);
        if (!sub) return;
        const manager = sub.getLive2DManager();
        const currentModel = manager.getCurrentModel();
        if (!currentModel) {
          console.error('[ParameterUI] No current model found for reset');
          return;
        }

        sliderElements.forEach((elements, idx) => {
          try {
            if (typeof (currentModel as any).clearParameterOverride === 'function') {
              (currentModel as any).clearParameterOverride(elements.paramId);
            } else if (typeof (currentModel as any).queueParameterChange === 'function') {
              (currentModel as any).queueParameterChange(elements.paramId, elements.defaultValue);
            }

            elements.slider.value = elements.defaultValue.toString();
            elements.display.textContent = elements.defaultValue.toFixed(2);
          } catch (e) {
            console.error('[ParameterUI] Failed resetting parameter:', elements.paramId, e);
          }
        });
      } catch (e) {
        console.error('[ParameterUI] Reset All failed', e);
      }
    });

    controlsContainer.appendChild(refreshBtn);
    controlsContainer.appendChild(resetAllBtn);

    // Append the controls container to the windowDiv
    if (!existingControls) windowDiv.appendChild(controlsContainer);
  }
  // Expose update function so other modules (e.g., motion list) can trigger it
  (window as any).updateParameterList = updateParameterList;
}

function updateDockedWindowsPositions(): void {
  const leftWindowIds = ['motion-list-window', 'expression-list-window'];
  const rightWindowIds = ['parameter-window'];
  const gap = 10;

  // Layout left-docked windows in a row from the left side
  let x = 10; // starting left margin
  for (const id of leftWindowIds) {
    const el = document.getElementById(id) as HTMLDivElement;
    if (!el) continue;
    if (getComputedStyle(el).display === 'none') continue;
    el.style.top = '40px';
    // clamp width to viewport if needed
    const maxWidth = window.innerWidth - 40; // leave margins
    const elWidth = Math.min(el.offsetWidth || 220, maxWidth);
    el.style.width = `${elWidth}px`;
    el.style.left = `${x}px`;
    // Clear right property (we manage left-side windows)
    el.style.right = '';
    x += elWidth + gap;
  }

  // Layout right-docked windows in a row from the right side
  let rightX = 10; // distance from the right edge
  for (const id of rightWindowIds) {
    const el = document.getElementById(id) as HTMLDivElement;
    if (!el) continue;
    if (getComputedStyle(el).display === 'none') continue;
    el.style.top = '40px';
    const maxWidth = window.innerWidth - 40; // leave margins
    const elWidth = Math.min(el.offsetWidth || 220, maxWidth);
    el.style.width = `${elWidth}px`;
    el.style.right = `${rightX}px`;
    // Clear left property (we manage right-side windows)
    el.style.left = '';
    rightX += elWidth + gap;
  }
}


function setupImportModelUI(): void {
  const importBtn = document.getElementById('import-model-btn') as HTMLButtonElement;
  
  if (!importBtn) {
    console.error('Import button not found in control bar.');
    return;
  }

  const fileInput = document.createElement('input');
  fileInput.type = 'file';
  fileInput.webkitdirectory = true;
  fileInput.multiple = true;
  fileInput.accept = '.json,.moc3,.png,.wav,.mp3';
  fileInput.style.display = 'none';
  
  importBtn.addEventListener('click', () => fileInput.click());
  
  fileInput.addEventListener('change', async () => {
    const files = Array.from(fileInput.files || []);
    if (files.length === 0) return;
    const pathToFile = new Map<string, File>();

    for (const f of files) {
      const rel: string = (f.webkitRelativePath || f.name).replace(/\\/g, '/');
      pathToFile.set(rel, f);
    }

    const modelJsonEntry = files.find(f => f.name.endsWith('.model3.json'));

    if (!modelJsonEntry) {
      alert('No .model3.json found in the selected folder.');
      return;
    }

    const modelJsonPath: string = (
      modelJsonEntry.webkitRelativePath || modelJsonEntry.name
    ).replace(/\\/g, '/');
    const rootDir = modelJsonPath.substring(
      0,
      modelJsonPath.lastIndexOf('/') + 1
    );
    const relativeMap = new Map<string, File>();

    for (const [full, f] of pathToFile.entries()) {
      if (full.startsWith(rootDir)) {
        const rel = full.substring(rootDir.length);
        relativeMap.set(rel, f);
      }
    }

    try {
      const appDelegate = LAppDelegate.getInstance();
      const subdelegates = appDelegate.getSubdelegates();

      if (!subdelegates || subdelegates.getSize() === 0) {
        alert('App not initialized yet.');
        return;
      }

      const sub = subdelegates.at(0);
      const live2DManager = sub.getLive2DManager();
      live2DManager.loadModelFromLocalFileMap(relativeMap);
    } catch (e) {
      console.error('Failed to import model:', e);
      alert('Failed to import model. See console for details.');
    }
  });
  
  document.body.appendChild(fileInput);
}

function setupControlBarUI(): void {
  const bgBtn = document.getElementById('btn-bg-picker') as HTMLButtonElement | null;
  const bgInput = document.getElementById('bg-color-input') as HTMLInputElement | null;
  const resetBtn = document.getElementById('btn-reset-view') as HTMLButtonElement;
  const zoomInBtn = document.getElementById('btn-zoom-in') as HTMLButtonElement;
  const zoomOutBtn = document.getElementById('btn-zoom-out') as HTMLButtonElement;

  if (!resetBtn || !zoomInBtn || !zoomOutBtn) {
    console.warn('Control bar buttons not found. Skipping control wiring.');
    return;
  }

  // Prevent underlying app interactions while using the controls
  const toggleWindowBtn = document.getElementById('toggle-window-btn') as HTMLButtonElement;
  const toggleParamsBtn = document.getElementById('toggle-params-btn') as HTMLButtonElement;
  const toggleExprBtn = document.getElementById('toggle-expr-btn') as HTMLButtonElement;
  const importBtn = document.getElementById('import-model-btn') as HTMLButtonElement;
  const setActive = (v: boolean) => setUIElementActive(v);
  const interactiveEls: HTMLElement[] = [resetBtn, zoomInBtn, zoomOutBtn, toggleWindowBtn, toggleParamsBtn, toggleExprBtn];
  if (bgBtn) interactiveEls.push(bgBtn);
  if (importBtn) interactiveEls.push(importBtn);
  interactiveEls.forEach((el) => {
    el.addEventListener('pointerdown', () => setActive(true), { passive: true });
    el.addEventListener('pointerup', () => setActive(false), { passive: true });
    el.addEventListener('pointerleave', () => setActive(false), { passive: true });
    el.addEventListener('touchstart', () => setActive(true), { passive: true });
    el.addEventListener('touchend', () => setActive(false), { passive: true });
  });

  const getPrimaryView = () => {
    const appDelegate = LAppDelegate.getInstance();
    const subs = appDelegate.getSubdelegates();
    if (!subs || subs.getSize() === 0) return null;
    const sub = subs.at(0);
    return sub ? sub.getView() : null;
  };

  resetBtn.addEventListener('click', () => {
    const view = getPrimaryView();
    if (!view) return;
    view.resetView();
  });

  // Fit view removed - use reset + zoom buttons for adjustments

  zoomInBtn.addEventListener('click', () => {
    const view = getPrimaryView();
    if (!view) return;
    const appDelegate = LAppDelegate.getInstance();
    const subs = appDelegate.getSubdelegates();
    if (!subs || subs.getSize() === 0) return;
    const sub = subs.at(0);
    if (!sub) return;
    const canvas = sub.getCanvas();
    const cx = canvas.width * 0.5;
    const cy = canvas.height * 0.5;
    view.zoomByFactor(1.15, cx, cy);
  });

  zoomOutBtn.addEventListener('click', () => {
    const view = getPrimaryView();
    if (!view) return;
    const appDelegate = LAppDelegate.getInstance();
    const subs = appDelegate.getSubdelegates();
    if (!subs || subs.getSize() === 0) return;
    const sub = subs.at(0);
    if (!sub) return;
    const canvas = sub.getCanvas();
    const cx = canvas.width * 0.5;
    const cy = canvas.height * 0.5;
    view.zoomByFactor(1.0 / 1.15, cx, cy);
  });

  // Background color picker wiring: persist background color and update swatch
  // Background color picker wiring: persist background color and update swatch
  const savedBg = localStorage.getItem('app_bg_color') || '#fff';

  // Helper function to convert hex color to RGB values (0-1 range for WebGL)
  const hexToRgb = (hex: string): { r: number; g: number; b: number } => {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    return result ? {
      r: parseInt(result[1], 16) / 255,
      g: parseInt(result[2], 16) / 255,
      b: parseInt(result[3], 16) / 255
    } : { r: 255, g: 255, b: 255 };
  };

  // Helper function to apply background color to WebGL contexts
  const applyBackgroundColor = (color: string) => {
    document.body.style.backgroundColor = color;

    // Convert color to RGB for WebGL
    const rgb = hexToRgb(color);

    // Find and update all canvas elements
    const canvases = document.querySelectorAll('canvas');
    canvases.forEach((canvas) => {
      canvas.style.backgroundColor = color;

      // Try to get WebGL context and set clear color
      const gl = canvas.getContext('webgl') || canvas.getContext('webgl2') || canvas.getContext('experimental-webgl');
      if (gl) {
        (gl as WebGLRenderingContext).clearColor(rgb.r, rgb.g, rgb.b, 1.0);
      }
    });

    // Also try to get canvas and GL context from the app delegate
    try {
      const appDelegate = LAppDelegate.getInstance();
      const subs = appDelegate.getSubdelegates();
      if (subs && subs.getSize() > 0) {
        for (let i = 0; i < subs.getSize(); i++) {
          const sub = subs.at(i);
          if (sub) {
            const canvas = sub.getCanvas();
            if (canvas) {
              canvas.style.backgroundColor = color;
              const gl = (sub as any).gl || (sub as any)._gl;
              if (gl) {
                gl.clearColor(rgb.r, rgb.g, rgb.b, 1.0);
              }
            }
          }
        }
      }
    } catch (e) {
      console.log('Canvas not yet available from delegate:', e);
    }
  };

  // Apply saved color on load (might need to retry after canvas is created)
  applyBackgroundColor(savedBg);

  // Retry applying color after delays to catch canvas creation
  setTimeout(() => applyBackgroundColor(savedBg), 500);
  setTimeout(() => applyBackgroundColor(savedBg), 1500);

  if (bgInput && bgBtn) {
    // Set initial value
    bgInput.value = savedBg;
    const swatch = bgBtn.querySelector('.bg-swatch') as HTMLElement | null;
    if (swatch) swatch.style.background = savedBg;

    // Button click triggers color picker
    bgBtn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      bgInput.click();
    });

    // Color input change handler
    const handleColorChange = (ev: Event) => {
      const color = (ev.target as HTMLInputElement).value;
      applyBackgroundColor(color);
      localStorage.setItem('app_bg_color', color);
      (window as any).live2dClearColor = hexToRgb(color); // Update global clear color
      const swatch = bgBtn.querySelector('.bg-swatch') as HTMLElement | null;
      if (swatch) swatch.style.background = color;
    };

    bgInput.addEventListener('input', handleColorChange);
    bgInput.addEventListener('change', handleColorChange);
  }

  // Expose the function globally so it can be called from anywhere
  (window as any).setLive2DBackgroundColor = applyBackgroundColor;

  // Store the desired clear color globally
  (window as any).live2dClearColor = hexToRgb(savedBg);
}

function setupExpressionUI(): void {
  const toggleBtn = document.getElementById('toggle-expr-btn') as HTMLButtonElement;
  const windowDiv = document.getElementById('expression-list-window') as HTMLDivElement;
  const listDiv = document.getElementById('expression-list') as HTMLDivElement;
  const randomBtn = document.getElementById('expr-random-btn') as HTMLButtonElement;
  const resetBtn = document.getElementById('expr-reset-btn') as HTMLButtonElement;

  if (!toggleBtn || !windowDiv || !listDiv || !randomBtn || !resetBtn) {
    console.error('Expression UI elements not found in HTML.');
    return;
  }

  let isWindowVisible = false;

  // Accessibility attributes for expression panel
  toggleBtn.setAttribute('aria-controls', 'expression-list-window');
  toggleBtn.setAttribute('aria-expanded', 'false');
  windowDiv.setAttribute('role', 'dialog');
  windowDiv.setAttribute('aria-hidden', 'true');
  windowDiv.setAttribute('tabindex', '0');

  toggleBtn.addEventListener('click', () => {
    isWindowVisible = !isWindowVisible;
    windowDiv.style.display = isWindowVisible ? 'block' : 'none';
    toggleBtn.setAttribute('aria-expanded', String(isWindowVisible));
    windowDiv.setAttribute('aria-hidden', String(!isWindowVisible));
    updateExpressionList();
    updateDockedWindowsPositions();
    if (isWindowVisible) {
      const focusTarget = listDiv.querySelector('button') as HTMLElement | null;
      if (focusTarget) focusTarget.focus();
    } else {
      toggleBtn.focus();
    }
  });

  // Keyboard nav in expression panel
  windowDiv.addEventListener('keydown', (e) => {
    const active = document.activeElement as HTMLElement | null;
    if (e.key === 'ArrowDown') { e.preventDefault(); focusRelative(windowDiv, active, 'next'); }
    if (e.key === 'ArrowUp') { e.preventDefault(); focusRelative(windowDiv, active, 'prev'); }
    if (e.key === 'Enter' && active && active.tagName === 'BUTTON') {
      (active as HTMLButtonElement).click();
    }
  });

  // Prevent dragging while interacting with UI
  [toggleBtn, randomBtn, resetBtn].forEach((el) => {
    el.addEventListener('pointerdown', () => setUIElementActive(true));
    el.addEventListener('pointerup', () => setUIElementActive(false));
    el.addEventListener('pointerleave', () => setUIElementActive(false));
    el.addEventListener('touchstart', () => setUIElementActive(true));
    el.addEventListener('touchend', () => setUIElementActive(false));
  });

  randomBtn.addEventListener('click', () => {
    const appDelegate = LAppDelegate.getInstance();
    const subs = appDelegate.getSubdelegates();
    if (!subs || subs.getSize() === 0) return;
    const sub = subs.at(0);
    if (!sub) return;
    const manager = sub.getLive2DManager();
    const model = manager.getCurrentModel();
    if (!model) return;
    model.setRandomExpression();
  });

  resetBtn.addEventListener('click', () => {
    const appDelegate = LAppDelegate.getInstance();
    const subs = appDelegate.getSubdelegates();
    if (!subs || subs.getSize() === 0) return;
    const sub = subs.at(0);
    if (!sub) return;
    const manager = sub.getLive2DManager();
    const model = manager.getCurrentModel();
    if (!model) return;
    // Reset to default expression (if exists index 0)
    const names = model.getLoadedExpressionNames();
    if (names.length > 0) {
      model.setExpression(names[0]);
    }
  });

  
  function updateExpressionList(): void {
    listDiv.innerHTML = '';
    const appDelegate = LAppDelegate.getInstance();
    const subs = appDelegate.getSubdelegates();
    if (!subs || subs.getSize() === 0) {
      const msg = document.createElement('div');
      msg.textContent = 'No model loaded';
      msg.style.color = '#aaa';
      listDiv.appendChild(msg);
      return;
    }

    const sub = subs.at(0);
    const manager = sub.getLive2DManager();
    const currentModel = manager.getCurrentModel();
    if (!currentModel) {
      const msg = document.createElement('div');
      msg.textContent = 'No model loaded';
      msg.style.color = '#aaa';
      listDiv.appendChild(msg);
      return;
    }

    const names = manager.getCurrentModelLoadedExpressionNames();
    if (!names || names.length === 0) {
      const msg = document.createElement('div');
      msg.textContent = 'No expressions loaded';
      msg.style.color = '#aaa';
      listDiv.appendChild(msg);
      return;
    }

    names.forEach((name: string) => {
      // create a wrapper so buttons get vertical spacing like motion-list
      const wrapper = document.createElement('div');
      wrapper.style.marginBottom = '6px';

      const button = document.createElement('button');
      button.className = 'motion-btn';
      button.style.display = 'block';
      button.textContent = name;
      // Prevent model drag while interacting with expression buttons
      button.addEventListener('pointerdown', () => setUIElementActive(true));
      button.addEventListener('pointerup', () => setUIElementActive(false));
      button.addEventListener('pointerleave', () => setUIElementActive(false));
      button.addEventListener('touchstart', () => setUIElementActive(true));
      button.addEventListener('touchend', () => setUIElementActive(false));

      button.addEventListener('click', () => {
        const model = manager.getCurrentModel();
        if (!model) return;
        model.setExpression(name);
      });
      wrapper.appendChild(button);
      listDiv.appendChild(wrapper);
    });
    // Reposition to reflect new expression list size
    updateDockedWindowsPositions();
  }

  // Expose update function so other modules (e.g., motion list) can trigger it
  (window as any).updateExpressionList = updateExpressionList;
}

window.addEventListener(
  'load',
  (): void => {
    setupMotionListUI();
    setupParameterUI();
    setupExpressionUI();
    setupControlBarUI();
    setupImportModelUI();

    // Close/Toggle UI panels when user presses certain keys (M/P/E) or Escape (unless focused in an input)
    window.addEventListener('keydown', (e) => {
      const active = document.activeElement as HTMLElement | null;
      const isTyping = active && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA');
      if (isTyping) return; // don't trigger shortcuts while typing

      // Don't handle when modifier keys are pressed (so Ctrl/Cmd+M etc. are allowed for other actions)
      if (e.altKey || e.ctrlKey || e.metaKey) return;

      switch (e.key) {
        case 'Escape': {
          const ids = ['motion-list-window', 'parameter-window', 'expression-list-window'];
          for (const id of ids) {
            const el = document.getElementById(id) as HTMLDivElement | null;
            if (el && getComputedStyle(el).display !== 'none') el.style.display = 'none';
          }
          updateDockedWindowsPositions();
          break;
        }
        case 'm':
        case 'M': {
          const btn = document.getElementById('toggle-window-btn') as HTMLElement | null;
          if (btn) btn.click();
          break;
        }
        case 'p':
        case 'P': {
          const btn = document.getElementById('toggle-params-btn') as HTMLElement | null;
          if (btn) btn.click();
          break;
        }
        case 'e':
        case 'E': {
          const btn = document.getElementById('toggle-expr-btn') as HTMLElement | null;
          if (btn) btn.click();
          break;
        }
        case 'b':
        case 'B': {
          const btn = document.getElementById('btn-bg-picker') as HTMLElement | null;
          if (btn) btn.click();
          break;
        }
        default:
          // no-op
      }
    });

    if (!LAppDelegate.getInstance().initialize()) {
      return;
    }

    LAppDelegate.getInstance().run();
  },
  {
    passive: true
  }
);
window.addEventListener(
  'beforeunload',
  (): void => LAppDelegate.releaseInstance(),
  {
    passive: true
  }
);
