export class LAppModel extends CubismUserModel {
  private _onModelLoadCompleteCallback: (() => void) | null = null;
  private _localFetch: (
    input: RequestInfo,
    init?: RequestInit
  ) => Promise<Response>;

  private _subdelegate: LAppSubdelegate;
  public constructor() {
    super();
    this._modelSetting = null;
    this._modelHomeDir = null;
    this._userTimeSeconds = 0.0;
    this._eyeBlinkIds = new csmVector<CubismIdHandle>();
    this._lipSyncIds = new csmVector<CubismIdHandle>();
    this._motions = new csmMap<string, ACubismMotion>();
    this._expressions = new csmMap<string, ACubismMotion>();
    this._hitArea = new csmVector<csmRect>();
    this._userArea = new csmVector<csmRect>();
    this._idParamAngleX = CubismFramework.getIdManager().getId(
      CubismDefaultParameterId.ParamAngleX
    );
    this._idParamAngleY = CubismFramework.getIdManager().getId(
      CubismDefaultParameterId.ParamAngleY
    );
    this._idParamAngleZ = CubismFramework.getIdManager().getId(
      CubismDefaultParameterId.ParamAngleZ
    );
    this._idParamEyeBallX = CubismFramework.getIdManager().getId(
      CubismDefaultParameterId.ParamEyeBallX
    );
    this._idParamEyeBallY = CubismFramework.getIdManager().getId(
      CubismDefaultParameterId.ParamEyeBallY
    );
    this._idParamBodyAngleX = CubismFramework.getIdManager().getId(
      CubismDefaultParameterId.ParamBodyAngleX
    );

    if (LAppDefine.MOCConsistencyValidationEnable) {
      this._mocConsistency = true;
    }

    if (LAppDefine.MotionConsistencyValidationEnable) {
      this._motionConsistency = true;
    }

    this._state = LoadStep.LoadAssets;
    this._expressionCount = 0;
    this._textureCount = 0;
    this._motionCount = 0;
    this._allMotionCount = 0;
    this._wavFileHandler = new LAppWavFileHandler();
    this._consistency = false;
    this._localFetch = fetch.bind(window);
  }

  public loadAssets(dir: string, fileName: string): void {
    this._modelHomeDir = dir;
    fetch(`${this._modelHomeDir}${fileName}`)
      .then(response => response.arrayBuffer())
      .then(arrayBuffer => {
        const setting: ICubismModelSetting = new CubismModelSettingJson(
          arrayBuffer,
          arrayBuffer.byteLength
        );
        this._state = LoadStep.LoadModel;
        this.setupModel(setting);
      })
      .catch(error => {
        CubismLogError(
          `Failed to load file ${this._modelHomeDir}${fileName}. Error: ${String(error)}`
        );
      });
  }

  public loadAssetsFromFileMap(
    fileMap: Map<string, File>,
    modelJsonName: string
  ): void {
    this._modelHomeDir = '';
    const normalizedMap = new Map<string, File>();

    for (const [k, v] of fileMap.entries()) {
      const norm = k.replace(/^\.\//, '').toLowerCase();
      normalizedMap.set(norm, v);
    }

    const resolveLocalFile = (rawPath: string): File | null => {
      const p0 = rawPath.replace(/^\.\//, '');
      const candidates = [
        p0,
        decodeURIComponent(p0),
        p0.toLowerCase(),
        decodeURIComponent(p0.toLowerCase())
      ];

      for (const c of candidates) {
        if (fileMap.has(c)) return fileMap.get(c);
        if (normalizedMap.has(c.toLowerCase()))
          return normalizedMap.get(c.toLowerCase());
      }

      return null;
    };

    const readAsArrayBuffer = (path: string): Promise<ArrayBuffer> => {
      const f = resolveLocalFile(path);
      if (!f)
        return Promise.reject(
          new Error(`File not found in local map: ${path}`)
        );
      return f.arrayBuffer();
    };

    readAsArrayBuffer(modelJsonName)
      .then(arrayBuffer => {
        const setting: ICubismModelSetting = new CubismModelSettingJson(
          arrayBuffer,
          arrayBuffer.byteLength
        );

        this._localFetch = (
          input: RequestInfo,
          init?: RequestInit
        ): Promise<Response> => {
          const url = typeof input === 'string' ? input : input.url;

          if (/^https?:\/\//i.test(url)) {
            return fetch(input, init);
          }

          const rel = url.replace(/^\.\//, '');
          const f = resolveLocalFile(rel);

          if (!f) {
            console.error(`[LocalFetch] File not found for ${rel}`);
            return Promise.reject(new Error(`Local file not found for ${rel}`));
          }

          const blobPromise = Promise.resolve(f);
          return blobPromise.then(b => new Response(b));
        };

        (this as any)._customFetcher = this._localFetch;
        this._state = LoadStep.LoadModel;
        this.setupModelWithCustomFetch(setting, this._localFetch);
      })
      .catch(error => {
        CubismLogError(`Failed to load local model assets: ${String(error)}`);
      });
  }

  private setupModel(setting: ICubismModelSetting): void {
    this.setupModelWithCustomFetch(setting, fetch.bind(window));
  }

  private setupModelWithCustomFetch(
    setting: ICubismModelSetting,
    fetcher: (input: RequestInfo, init?: RequestInit) => Promise<Response>
  ): void {
    this._updating = true;
    this._initialized = false;
    this._modelSetting = setting;

    if (this._modelSetting.getModelFileName() != '') {
      const modelFileName = this._modelSetting.getModelFileName();
      fetcher(`${this._modelHomeDir}${modelFileName}`)
        .then(response => {
          if (response.ok) {
            return response.arrayBuffer();
          } else if (response.status >= 400) {
            CubismLogError(
              `Failed to load file ${this._modelHomeDir}${modelFileName}. Status: ${response.status}`
            );
            return new ArrayBuffer(0);
          }
        })
        .then(arrayBuffer => {
          this.loadModel(arrayBuffer, this._mocConsistency);
          this._state = LoadStep.LoadExpression;
          loadCubismExpression();
        });
      this._state = LoadStep.WaitLoadModel;
    } else {
      LAppPal.printMessage('Model data does not exist.');
    }

    const loadCubismExpression = (): void => {
      if (this._modelSetting.getExpressionCount() > 0) {
        const count: number = this._modelSetting.getExpressionCount();

        for (let i = 0; i < count; i++) {
          const expressionName = this._modelSetting.getExpressionName(i);
          const expressionFileName =
            this._modelSetting.getExpressionFileName(i);
          fetcher(`${this._modelHomeDir}${expressionFileName}`)
            .then(response => {
              if (response.ok) {
                return response.arrayBuffer();
              } else if (response.status >= 400) {
                CubismLogError(
                  `Failed to load file ${this._modelHomeDir}${expressionFileName}. Status: ${response.status}`
                );
                return new ArrayBuffer(0);
              }
            })
            .then(arrayBuffer => {
              const motion: ACubismMotion = this.loadExpression(
                arrayBuffer,
                arrayBuffer.byteLength,
                expressionName
              );

              if (this._expressions.getValue(expressionName) != null) {
                ACubismMotion.delete(
                  this._expressions.getValue(expressionName)
                );
                this._expressions.setValue(expressionName, null);
              }

              this._expressions.setValue(expressionName, motion);
              this._expressionCount++;

              if (this._expressionCount >= count) {
                this._state = LoadStep.LoadPhysics;
                loadCubismPhysics();
              }
            });
        }

        this._state = LoadStep.WaitLoadExpression;
      } else {
        this._state = LoadStep.LoadPhysics;
        loadCubismPhysics();
      }
    };

    const loadCubismPhysics = (): void => {
      if (this._modelSetting.getPhysicsFileName() != '') {
        const physicsFileName = this._modelSetting.getPhysicsFileName();
        fetcher(`${this._modelHomeDir}${physicsFileName}`)
          .then(response => {
            if (response.ok) {
              return response.arrayBuffer();
            } else if (response.status >= 400) {
              CubismLogError(
                `Failed to load file ${this._modelHomeDir}${physicsFileName}. Status: ${response.status}`
              );
              return new ArrayBuffer(0);
            }
          })
          .then(arrayBuffer => {
            this.loadPhysics(arrayBuffer, arrayBuffer.byteLength);
            this._state = LoadStep.LoadPose;
            loadCubismPose();
          });
        this._state = LoadStep.WaitLoadPhysics;
      } else {
        this._state = LoadStep.LoadPose;
        loadCubismPose();
      }
    };

    const loadCubismPose = (): void => {
      if (this._modelSetting.getPoseFileName() != '') {
        const poseFileName = this._modelSetting.getPoseFileName();
        fetcher(`${this._modelHomeDir}${poseFileName}`)
          .then(response => {
            if (response.ok) {
              return response.arrayBuffer();
            } else if (response.status >= 400) {
              CubismLogError(
                `Failed to load file ${this._modelHomeDir}${poseFileName}. Status: ${response.status}`
              );
              return new ArrayBuffer(0);
            }
          })
          .then(arrayBuffer => {
            this.loadPose(arrayBuffer, arrayBuffer.byteLength);
            this._state = LoadStep.SetupEyeBlink;
            setupEyeBlink();
          });
        this._state = LoadStep.WaitLoadPose;
      } else {
        this._state = LoadStep.SetupEyeBlink;
        setupEyeBlink();
      }
    };

    const setupEyeBlink = (): void => {
      if (this._modelSetting.getEyeBlinkParameterCount() > 0) {
        this._eyeBlink = CubismEyeBlink.create(this._modelSetting);
        this._state = LoadStep.SetupBreath;
      }

      setupBreath();
    };

    const setupBreath = (): void => {
      this._breath = CubismBreath.create();
      const breathParameters: csmVector<BreathParameterData> = new csmVector();
      breathParameters.pushBack(
        new BreathParameterData(this._idParamAngleX, 0.0, 15.0, 6.5345, 0.5)
      );
      breathParameters.pushBack(
        new BreathParameterData(this._idParamAngleY, 0.0, 8.0, 3.5345, 0.5)
      );
      breathParameters.pushBack(
        new BreathParameterData(this._idParamAngleZ, 0.0, 10.0, 5.5345, 0.5)
      );
      breathParameters.pushBack(
        new BreathParameterData(this._idParamBodyAngleX, 0.0, 4.0, 15.5345, 0.5)
      );
      breathParameters.pushBack(
        new BreathParameterData(
          CubismFramework.getIdManager().getId(
            CubismDefaultParameterId.ParamBreath
          ),
          0.5,
          0.5,
          3.2345,
          1
        )
      );
      this._breath.setParameters(breathParameters);
      this._state = LoadStep.LoadUserData;
      loadUserData();
    };

    const loadUserData = (): void => {
      if (this._modelSetting.getUserDataFile() != '') {
        const userDataFile = this._modelSetting.getUserDataFile();
        fetcher(`${this._modelHomeDir}${userDataFile}`)
          .then(response => {
            if (response.ok) {
              return response.arrayBuffer();
            } else if (response.status >= 400) {
              CubismLogError(
                `Failed to load file ${this._modelHomeDir}${userDataFile}. Status: ${response.status}`
              );
              return new ArrayBuffer(0);
            }
          })
          .then(arrayBuffer => {
            this.loadUserData(arrayBuffer, arrayBuffer.byteLength);
            this._state = LoadStep.SetupEyeBlinkIds;
            setupEyeBlinkIds();
          });
        this._state = LoadStep.WaitLoadUserData;
      } else {
        this._state = LoadStep.SetupEyeBlinkIds;
        setupEyeBlinkIds();
      }
    };

    const setupEyeBlinkIds = (): void => {
      const eyeBlinkIdCount: number =
        this._modelSetting.getEyeBlinkParameterCount();

      for (let i = 0; i < eyeBlinkIdCount; ++i) {
        this._eyeBlinkIds.pushBack(
          this._modelSetting.getEyeBlinkParameterId(i)
        );
      }

      this._state = LoadStep.SetupLipSyncIds;
      setupLipSyncIds();
    };

    const setupLipSyncIds = (): void => {
      const lipSyncIdCount = this._modelSetting.getLipSyncParameterCount();

      for (let i = 0; i < lipSyncIdCount; ++i) {
        this._lipSyncIds.pushBack(this._modelSetting.getLipSyncParameterId(i));
      }

      this._state = LoadStep.SetupLayout;
      setupLayout();
    };

    const setupLayout = (): void => {
      const layout: csmMap<string, number> = new csmMap<string, number>();

      if (this._modelSetting == null || this._modelMatrix == null) {
        CubismLogError('Failed to setupLayout().');
        return;
      }

      this._modelSetting.getLayoutMap(layout);
      this._modelMatrix.setupFromLayout(layout);
      this._state = LoadStep.LoadMotion;
      loadCubismMotion();
    };

    const loadCubismMotion = (): void => {
      this._state = LoadStep.WaitLoadMotion;
      this._model.saveParameters();
      this._allMotionCount = 0;
      this._motionCount = 0;
      const group: string[] = [];
      const motionGroupCount: number = this._modelSetting.getMotionGroupCount();

      for (let i = 0; i < motionGroupCount; i++) {
        group[i] = this._modelSetting.getMotionGroupName(i);
        this._allMotionCount += this._modelSetting.getMotionCount(group[i]);
      }

      for (let i = 0; i < motionGroupCount; i++) {
        this.preLoadMotionGroupWithFetcher(group[i], fetcher);
      }

      if (motionGroupCount == 0) {
        this._state = LoadStep.LoadTexture;
        this._motionManager.stopAllMotions();
        this._updating = false;
        this._initialized = true;
        this.createRenderer();
        this.setupTextures();
        this.getRenderer().startUp(this._subdelegate.getGlManager().getGl());
      }
    };
  }

  private setupTextures(): void {
    const usePremultiply = true;

    if (this._state == LoadStep.LoadTexture) {
      const textureCount: number = this._modelSetting.getTextureCount();

      for (
        let modelTextureNumber = 0;
        modelTextureNumber < textureCount;
        modelTextureNumber++
      ) {
        if (this._modelSetting.getTextureFileName(modelTextureNumber) == '') {
          console.log('getTextureFileName null');
          continue;
        }

        let texturePath =
          this._modelSetting.getTextureFileName(modelTextureNumber);
        texturePath = this._modelHomeDir + texturePath;

        const onLoad = (textureInfo: TextureInfo): void => {
          this.getRenderer().bindTexture(modelTextureNumber, textureInfo.id);
          this._textureCount++;

          if (this._textureCount >= textureCount) {
            this._state = LoadStep.CompleteSetup;
          }
        };

        const localFetch = this._localFetch;

        if (localFetch) {
          localFetch(texturePath)
            .then((resp: Response) => resp.blob())
            .then((blob: Blob) => {
              const url = URL.createObjectURL(blob);
              this._subdelegate
                .getTextureManager()
                .createTextureFromPngFile(
                  url,
                  usePremultiply,
                  (ti: TextureInfo) => {
                    onLoad(ti);
                    setTimeout(() => URL.revokeObjectURL(url), 10000);
                  }
                );
            });
        } else {
          this._subdelegate
            .getTextureManager()
            .createTextureFromPngFile(texturePath, usePremultiply, onLoad);
        }

        this.getRenderer().setIsPremultipliedAlpha(usePremultiply);
      }

      this._state = LoadStep.WaitLoadTexture;
    }
  }

  public reloadRenderer(): void {
    this.deleteRenderer();
    this.createRenderer();
    this.setupTextures();
  }


  private _persistentParameterOverrides = new Map<string, number>();

  public queueParameterChange(parameterIdString: string, value: number): void {
    this._persistentParameterOverrides.set(parameterIdString, value);
    console.log(`[LAppModel] Set parameter override: ${parameterIdString} = ${value}`);
  }

  public clearParameterOverride(parameterIdString: string): void {
    this._persistentParameterOverrides.delete(parameterIdString);
    console.log(`[LAppModel] Cleared parameter override: ${parameterIdString}`);
  }

  public update(): void {
    if (this._state != LoadStep.CompleteSetup) return;
    const deltaTimeSeconds: number = LAppPal.getDeltaTime();
    this._userTimeSeconds += deltaTimeSeconds;
    this._dragManager.update(deltaTimeSeconds);
    this._dragX = this._dragManager.getX();
    this._dragY = this._dragManager.getY();
    let motionUpdated = false;
    this._model.loadParameters();

    if (this._motionManager.isFinished()) {
      this.startRandomMotion(
        LAppDefine.MotionGroupIdle,
        LAppDefine.PriorityIdle
      );
    } else {
      motionUpdated = this._motionManager.updateMotion(
        this._model,
        deltaTimeSeconds
      );
    }

    this._model.saveParameters();

    if (!motionUpdated) {
      if (this._eyeBlink != null) {
        this._eyeBlink.updateParameters(this._model, deltaTimeSeconds);
      }
    }

    if (this._expressionManager != null) {
      this._expressionManager.updateMotion(this._model, deltaTimeSeconds);
    }

    this._model.addParameterValueById(this._idParamAngleX, this._dragX * 30);
    this._model.addParameterValueById(this._idParamAngleY, this._dragY * 30);
    this._model.addParameterValueById(
      this._idParamAngleZ,
      this._dragX * this._dragY * -30
    );
    this._model.addParameterValueById(
      this._idParamBodyAngleX,
      this._dragX * 10
    );
    this._model.addParameterValueById(this._idParamEyeBallX, this._dragX);
    this._model.addParameterValueById(this._idParamEyeBallY, this._dragY);

    if (this._breath != null) {
      this._breath.updateParameters(this._model, deltaTimeSeconds);
    }

    if (this._physics != null) {
      this._physics.evaluate(this._model, deltaTimeSeconds);
    }

    if (this._lipsync) {
      let value = 0.0;
      this._wavFileHandler.update(deltaTimeSeconds);
      value = this._wavFileHandler.getRms();

      for (let i = 0; i < this._lipSyncIds.getSize(); ++i) {
        this._model.addParameterValueById(this._lipSyncIds.at(i), value, 0.8);
      }
    }

    if (this._pose != null) {
      this._pose.updateParameters(this._model, deltaTimeSeconds);
    }

    // Apply persistent parameter overrides from the UI (applied every frame to prevent being overridden)
    if (this._persistentParameterOverrides.size > 0) {
      this._persistentParameterOverrides.forEach((value: number, parameterIdString: string) => {
        const cubismId = CubismFramework.getIdManager().getId(parameterIdString);
        this._model.setParameterValueById(cubismId, value);
      });
    }

    this._model.update();
  }

  public getLoadedMotionNames(): string[] {
    const names: string[] = [];

    for (let i = 0; i < this._motions.getSize(); i++) {
      const key = this._motions._keyValues[i].first;
      names.push(key);
    }

    return names;
  }

  public getLoadedExpressionNames(): string[] {
    const names: string[] = [];

    for (let i = 0; i < this._expressions.getSize(); i++) {
      const key = this._expressions._keyValues[i].first;
      names.push(key);
    }

    return names;
  }

  public startMotionByName(
    name: string,
    priority: number = LAppDefine.PriorityNormal
  ): CubismMotionQueueEntryHandle {
    const motion: CubismMotion = this._motions.getValue(name) as CubismMotion;

    if (motion) {
      if (priority == LAppDefine.PriorityForce) {
        this._motionManager.setReservePriority(priority);
      } else if (!this._motionManager.reserveMotion(priority)) {
        if (this._debugMode) {
          LAppPal.printMessage("[APP]can't start motion (priority conflict).");
        }

        return InvalidMotionQueueEntryHandleValue;
      }

      motion.setBeganMotionHandler(null);
      motion.setFinishedMotionHandler(null);

      if (this._debugMode) {
        LAppPal.printMessage(
          `[APP]start motion from loaded: [${name}] with priority ${priority}`
        );
      }

      return this._motionManager.startMotionPriority(motion, false, priority);
    } else {
      if (this._debugMode) {
        LAppPal.printMessage(
          `[APP]Motion not found in loaded motions: [${name}]`
        );
      }

      return InvalidMotionQueueEntryHandleValue;
    }
  }

  public async startMergedMotionFromNamesArray(
    names: string[],
    priority: number = LAppDefine.PriorityNormal
  ): Promise<boolean> {
    try {
      if (names.length < 2) {
        CubismLogError(
          '[LAppModel] startMergedMotionFromNamesArray requires at least 2 names.'
        );
        return false;
      }

      console.log(`[LAppModel] Merging ${names.length} motions:`, names);
      const jsonPromises: Promise<MotionJson>[] = [];
      const nameToIndexMap: Map<
        string,
        {
          group: string;
          index: number;
        }
      > = new Map();

      for (const name of names) {
        let group: string | null = null;
        let index: number | null = null;

        for (
          let gIndex = 0;
          gIndex < this._modelSetting.getMotionGroupCount();
          gIndex++
        ) {
          const groupTemp = this._modelSetting.getMotionGroupName(gIndex);

          for (
            let mIndex = 0;
            mIndex < this._modelSetting.getMotionCount(groupTemp);
            mIndex++
          ) {
            if (`${groupTemp}_${mIndex}` === name) {
              group = groupTemp;
              index = mIndex;
              break;
            }
          }

          if (group !== null) break;
        }

        if (group === null || index === null) {
          CubismLogError(
            `[LAppModel] Motion JSON path not found for name: ${name}`
          );
          return false;
        }

        nameToIndexMap.set(name, {
          group,
          index
        });
        const file1Name = this._modelSetting.getMotionFileName(group, index);
        const fetcher = (this as any)._customFetcher || fetch.bind(window);
        jsonPromises.push(
          fetcher(`${this._modelHomeDir}${file1Name}`).then((r: Response) => {
            if (!r.ok) throw new Error(`Failed to fetch motion ${file1Name}`);
            return r.json() as Promise<MotionJson>;
          })
        );
      }

      const jsonObjects: MotionJson[] = await Promise.all(jsonPromises);

      if (jsonObjects.length !== names.length) {
        CubismLogError(
          '[LAppModel] Failed to fetch all motion JSONs for merging.'
        );
        return false;
      }

      console.log(
        `[LAppModel] Fetched ${jsonObjects.length} JSONs for merging.`
      );
      let mergedJson: MotionJson | null = jsonObjects[0];

      for (let i = 1; i < jsonObjects.length; i++) {
        console.log(
          `[LAppModel] Merging motion ${names[i]} into current merged JSON...`
        );
        mergedJson = this.mergeMotionJson(mergedJson, jsonObjects[i]);

        if (!mergedJson) {
          CubismLogError(
            '[LAppModel] Failed to merge motion JSON due to calculation error during loop.'
          );
          return false;
        }
      }

      console.log(
        `[LAppModel] Final merged JSON created from ${names.length} motions.`
      );
      const jsonString = JSON.stringify(mergedJson);
      const encoder = new TextEncoder();
      const arrayBuffer = encoder.encode(jsonString).buffer;
      const mergedMotion = this.loadMotion(
        arrayBuffer,
        arrayBuffer.byteLength,
        `Merged_${names.join('_')}`,
        null,
        null,
        this._modelSetting,
        `Merged_${names.join('_')}`,
        0,
        this._motionConsistency
      );

      if (!mergedMotion) {
        CubismLogError(
          'Failed to create motion from final merged JSON data in startMergedMotionFromNamesArray.'
        );
        return false;
      }

      mergedMotion.setEffectIds(this._eyeBlinkIds, this._lipSyncIds);
      const handle = this._motionManager.startMotionPriority(
        mergedMotion,
        true,
        priority
      );

      if (handle !== InvalidMotionQueueEntryHandleValue) {
        if (this._debugMode) {
          LAppPal.printMessage(
            `[APP] Started merged motion from names array: [${names.join(', ')}]`
          );
        }

        console.log(
          `[LAppModel] Started merged motion from names array: [${names.join(', ')}]`
        );
        return true;
      } else {
        CubismLogError(
          'Failed to start merged motion from names array in startMergedMotionFromNamesArray.'
        );
        return false;
      }
    } catch (error) {
      CubismLogError(
        `Error in startMergedMotionFromNamesArray: ${String(error)}`
      );
      console.error(
        '[LAppModel] Error in startMergedMotionFromNamesArray:',
        error
      );
      return false;
    }
  }

  public startMotion(
    group: string,
    no: number,
    priority: number,
    onFinishedMotionHandler?: FinishedMotionCallback,
    onBeganMotionHandler?: BeganMotionCallback
  ): CubismMotionQueueEntryHandle {
    if (priority == LAppDefine.PriorityForce) {
      this._motionManager.setReservePriority(priority);
    } else if (!this._motionManager.reserveMotion(priority)) {
      if (this._debugMode) {
        LAppPal.printMessage("[APP]can't start motion.");
      }

      return InvalidMotionQueueEntryHandleValue;
    }

    const motionFileName = this._modelSetting.getMotionFileName(group, no);
    const name = `${group}_${no}`;
    let motion: CubismMotion = this._motions.getValue(name) as CubismMotion;
    let autoDelete = false;

    if (motion == null) {
      fetch(`${this._modelHomeDir}${motionFileName}`)
        .then(response => {
          if (response.ok) {
            return response.arrayBuffer();
          } else if (response.status >= 400) {
            CubismLogError(
              `Failed to load file ${this._modelHomeDir}${motionFileName}. Status: ${response.status}`
            );
            return new ArrayBuffer(0);
          }
        })
        .then(arrayBuffer => {
          motion = this.loadMotion(
            arrayBuffer,
            arrayBuffer.byteLength,
            null,
            onFinishedMotionHandler,
            onBeganMotionHandler,
            this._modelSetting,
            group,
            no,
            this._motionConsistency
          );
        });

      if (motion) {
        motion.setEffectIds(this._eyeBlinkIds, this._lipSyncIds);
        autoDelete = true;
      } else {
        CubismLogError("Can't start motion {0} .", motionFileName);
        this._motionManager.setReservePriority(LAppDefine.PriorityNone);
        return InvalidMotionQueueEntryHandleValue;
      }
    } else {
      motion.setBeganMotionHandler(onBeganMotionHandler);
      motion.setFinishedMotionHandler(onFinishedMotionHandler);
    }

    const voice = this._modelSetting.getMotionSoundFileName(group, no);

    if (voice && voice !== '') {
      const fullPath = this._modelHomeDir + voice;
      const customFetcher = (this as any)._customFetcher || fetch.bind(window);

      if (customFetcher) {
        (
          customFetcher as (
            input: RequestInfo,
            init?: RequestInit
          ) => Promise<Response>
        )(fullPath)
          .then((res: Response) => res.arrayBuffer())
          .then((buf: ArrayBuffer) => {
            this._wavFileHandler.loadWavFromArrayBuffer(buf, fullPath);
            const blob = new Blob([buf], {
              type: 'audio/wave'
            });
            const url = URL.createObjectURL(blob);
            const audio = new Audio(url);
            audio.play().catch(e => console.warn('Audio play failed:', e));
            audio.onended = () => URL.revokeObjectURL(url);
          });
      } else {
        this._wavFileHandler.start(fullPath);
        const audio = new Audio(fullPath);
        audio.play().catch(e => console.warn('Audio play failed:', e));
      }
    }

    if (this._debugMode) {
      LAppPal.printMessage(`[APP]start motion: [${group}_${no}]`);
    }

    return this._motionManager.startMotionPriority(
      motion,
      autoDelete,
      priority
    );
  }

  public startMultipleMotions(
    motions: Array<{
      group: string;
      no: number;
    }>,
    priority: number = LAppDefine.PriorityNormal
  ): CubismMotionQueueEntryHandle[] {
    const handles: CubismMotionQueueEntryHandle[] = [];

    for (const { group, no } of motions) {
      const motionFileName = this._modelSetting.getMotionFileName(group, no);
      const name = `${group}_${no}`;
      let motion: CubismMotion = this._motions.getValue(name) as CubismMotion;

      if (motion == null) {
        fetch(`${this._modelHomeDir}${motionFileName}`)
          .then(response =>
            response.ok ? response.arrayBuffer() : new ArrayBuffer(0)
          )
          .then(arrayBuffer => {
            motion = this.loadMotion(
              arrayBuffer,
              arrayBuffer.byteLength,
              null,
              null,
              null,
              this._modelSetting,
              group,
              no,
              this._motionConsistency
            );

            if (motion) {
              motion.setEffectIds(this._eyeBlinkIds, this._lipSyncIds);
              const handle = this._motionManager.startMotionPriority(
                motion,
                true,
                priority
              );
              handles.push(handle);
            }
          });
      } else {
        const handle = this._motionManager.startMotionPriority(
          motion,
          false,
          priority
        );
        handles.push(handle);
      }
    }

    return handles;
  }

  private calculateTotalPointCountAndSegmentCount(curves: MotionJsonCurve[]): {
    totalPoints: number;
    totalSegments: number;
  } {
    let totalPoints = 0;
    let totalSegments = 0;

    for (const curve of curves) {
      const segments = curve.Segments;
      let segmentPosition = 0;

      if (segments.length === 0) {
        if (segments.length === 0) {
          totalPoints += 1;
        }

        continue;
      }

      totalPoints += 1;
      segmentPosition += 2;

      while (segmentPosition < segments.length) {
        const segmentType = segments[segmentPosition];
        totalSegments += 1;

        if (segmentType === 0) {
          totalPoints += 1;
          segmentPosition += 3;
        } else if (segmentType === 1) {
          totalPoints += 3;
          segmentPosition += 7;
        } else if (segmentType === 2) {
          totalPoints += 1;
          segmentPosition += 3;
        } else if (segmentType === 3) {
          totalPoints += 1;
          segmentPosition += 3;
        } else {
          console.error(
            `[LAppModel] Unknown segment type: ${segmentType} in curve ${curve.Id} at segmentPosition ${segmentPosition}. Segments array: [${segments.join(', ')}]`
          );
          return {
            totalPoints: -1,
            totalSegments: -1
          };
        }
      }
    }

    return {
      totalPoints,
      totalSegments
    };
  }

  private mergeMotionJson(
    motion1: MotionJson,
    motion2: MotionJson
  ): MotionJson | null {
    const duration1 = motion1.Meta?.Duration || 0;
    const duration2 = motion2.Meta?.Duration || 0;
    const finalDuration = Math.max(duration1, duration2);
    const curveMap = new Map<string, MotionJsonCurve>();
    motion1.Curves.forEach((curve: MotionJsonCurve) => {
      curveMap.set(curve.Id, curve);
    });
    motion2.Curves.forEach((curve2: MotionJsonCurve) => {
      curveMap.set(curve2.Id, curve2);
    });
    const mergedCurves = Array.from(curveMap.values());
    const { totalPoints, totalSegments } =
      this.calculateTotalPointCountAndSegmentCount(mergedCurves);

    if (totalPoints < 0 || totalSegments < 0) {
      console.error(
        '[LAppModel] Failed to calculate TotalPoint/SegmentCount due to unknown segment type.'
      );
      return null;
    }

    return {
      Version: 3,
      Meta: {
        Duration: finalDuration,
        Fps: motion1.Meta?.Fps || motion2.Meta?.Fps || 30,
        Loop: motion1.Meta?.Loop ?? motion2.Meta?.Loop ?? false,
        CurveCount: mergedCurves.length,
        TotalSegmentCount: totalSegments,
        TotalPointCount: totalPoints,
        ...(motion1.Meta?.AreBeziersRestricted !== undefined && {
          AreBeziersRestricted: motion1.Meta.AreBeziersRestricted
        }),
        ...(motion2.Meta?.AreBeziersRestricted !== undefined && {
          AreBeziersRestricted: motion2.Meta.AreBeziersRestricted
        })
      },
      Curves: mergedCurves,
      ...(motion1.UserData && {
        UserData: motion1.UserData
      }),
      ...(!motion1.UserData &&
        motion2.UserData && {
        UserData: motion2.UserData
      })
    };
  }

  public async startMergedMotion(
    group1: string,
    no1: number,
    group2: string,
    no2: number,
    priority: number = LAppDefine.PriorityNormal
  ): Promise<CubismMotionQueueEntryHandle> {
    try {
      const file1Name = this._modelSetting.getMotionFileName(group1, no1);
      const file2Name = this._modelSetting.getMotionFileName(group2, no2);
      const [json1, json2] = await Promise.all<MotionJson>([
        fetch(`${this._modelHomeDir}${file1Name}`).then(r => {
          if (!r.ok) throw new Error(`Failed to fetch motion ${file1Name}`);
          return r.json() as Promise<MotionJson>;
        }),
        fetch(`${this._modelHomeDir}${file2Name}`).then(r => {
          if (!r.ok) throw new Error(`Failed to fetch motion ${file2Name}`);
          return r.json() as Promise<MotionJson>;
        })
      ]);
      const mergedJson = this.mergeMotionJson(json1, json2);

      if (!mergedJson) {
        CubismLogError('Failed to merge motion JSON due to calculation error.');
        return InvalidMotionQueueEntryHandleValue;
      }

      const jsonString = JSON.stringify(mergedJson);
      const encoder = new TextEncoder();
      const arrayBuffer = encoder.encode(jsonString).buffer;
      const motion = this.loadMotion(
        arrayBuffer,
        arrayBuffer.byteLength,
        null,
        null,
        null,
        this._modelSetting,
        `${group1}_${no1}_merged_with_${group2}_${no2}`,
        0,
        this._motionConsistency
      );

      if (!motion) {
        CubismLogError('Failed to create motion from merged JSON data.');
        return InvalidMotionQueueEntryHandleValue;
      }

      motion.setEffectIds(this._eyeBlinkIds, this._lipSyncIds);
      const handle = this._motionManager.startMotionPriority(
        motion,
        true,
        priority
      );

      if (this._debugMode) {
        LAppPal.printMessage(
          `[APP] Started merged motion: [${group1}_${no1}] + [${group2}_${no2}]`
        );
      }

      return handle;
    } catch (error) {
      CubismLogError(`Error in startMergedMotion: ${String(error)}`);
      return InvalidMotionQueueEntryHandleValue;
    }
  }

  public startRandomMotion(
    group: string,
    priority: number,
    onFinishedMotionHandler?: FinishedMotionCallback,
    onBeganMotionHandler?: BeganMotionCallback
  ): CubismMotionQueueEntryHandle {
    if (this._modelSetting.getMotionCount(group) == 0) {
      return InvalidMotionQueueEntryHandleValue;
    }

    const no: number = Math.floor(
      Math.random() * this._modelSetting.getMotionCount(group)
    );
    return this.startMotion(
      group,
      no,
      priority,
      onFinishedMotionHandler,
      onBeganMotionHandler
    );
  }

  public setExpression(expressionId: string): void {
    const motion: ACubismMotion = this._expressions.getValue(expressionId);

    if (this._debugMode) {
      LAppPal.printMessage(`[APP]expression: [${expressionId}]`);
    }

    if (motion != null) {
      this._expressionManager.startMotion(motion, false);
    } else {
      if (this._debugMode) {
        LAppPal.printMessage(`[APP]expression[${expressionId}] is null`);
      }
    }
  }

  public setRandomExpression(): void {
    if (this._expressions.getSize() == 0) {
      return;
    }

    const no: number = Math.floor(Math.random() * this._expressions.getSize());

    for (let i = 0; i < this._expressions.getSize(); i++) {
      if (i == no) {
        const name: string = this._expressions._keyValues[i].first;
        this.setExpression(name);
        return;
      }
    }
  }

  public motionEventFired(eventValue: csmString): void {
    CubismLogInfo('{0} is fired on LAppModel!!', eventValue.s);
  }

  public hitTest(hitArenaName: string, x: number, y: number): boolean {
    if (this._opacity < 1) {
      return false;
    }

    const count: number = this._modelSetting.getHitAreasCount();

    for (let i = 0; i < count; i++) {
      if (this._modelSetting.getHitAreaName(i) == hitArenaName) {
        const drawId: CubismIdHandle = this._modelSetting.getHitAreaId(i);
        return this.isHit(drawId, x, y);
      }
    }

    return false;
  }

  public setOnModelLoadCompleteCallback(callback: (() => void) | null): void {
    this._onModelLoadCompleteCallback = callback;

    if (callback) {
      console.log(
        `[LAppModel] Callback function stored successfully in this model instance.`
      );
    } else {
      console.log(
        `[LAppModel] Callback function cleared/set to null in this model instance.`
      );
    }
  }

  public preLoadMotionGroup(group: string): void {
    this.preLoadMotionGroupWithFetcher(group, fetch.bind(window));
  }

  public preLoadMotionGroupWithFetcher(
    group: string,
    fetcher: (input: RequestInfo, init?: RequestInit) => Promise<Response>
  ): void {
    const groupMotionCount = this._modelSetting.getMotionCount(group);
    console.log(
      `[LAppModel] preLoadMotionGroup: Starting to load ${groupMotionCount} motions for group: ${group}`
    );

    for (let i = 0; i < groupMotionCount; i++) {
      const motionFileName = this._modelSetting.getMotionFileName(group, i);
      const name = `${group}_${i}`;
      console.log(
        `[LAppModel] preLoadMotionGroup: Fetching motion ${name} (${motionFileName})`
      );
      fetcher(`${this._modelHomeDir}${motionFileName}`)
        .then(response => {
          if (response.ok) {
            console.log(
              `[LAppModel] preLoadMotionGroup: Fetched motion ${name} successfully.`
            );
            return response.arrayBuffer();
          } else if (response.status >= 400) {
            console.error(
              `[LAppModel] preLoadMotionGroup: Failed to fetch motion ${name} (${motionFileName}). Status: ${response.status}`
            );
            return new ArrayBuffer(0);
          }
        })
        .then(arrayBuffer => {
          const tmpMotion: CubismMotion = this.loadMotion(
            arrayBuffer,
            arrayBuffer.byteLength,
            name,
            null,
            null,
            this._modelSetting,
            group,
            i,
            this._motionConsistency
          );

          if (tmpMotion != null) {
            tmpMotion.setEffectIds(this._eyeBlinkIds, this._lipSyncIds);

            if (this._motions.getValue(name) != null) {
              ACubismMotion.delete(this._motions.getValue(name));
            }

            this._motions.setValue(name, tmpMotion);
            this._motionCount++;
            console.log(
              `[LAppModel] preLoadMotionGroup: Loaded motion ${name}. Motion count: ${this._motionCount} / ${this._allMotionCount}`
            );
          } else {
            this._allMotionCount--;
            console.warn(
              `[LAppModel] preLoadMotionGroup: Failed to load motion ${name}. Adjusted total count: ${this._allMotionCount}`
            );
          }

          console.log(
            `[LAppModel] preLoadMotionGroup: Checking if all motions loaded... Count: ${this._motionCount}, Total Expected: ${this._allMotionCount}`
          );

          if (this._motionCount >= this._allMotionCount) {
            console.log(
              `[LAppModel] preLoadMotionGroup: All motions loaded for this model instance (Count: ${this._motionCount}, Expected: ${this._allMotionCount}). Calling callback.`
            );
            this._state = LoadStep.LoadTexture;
            this._motionManager.stopAllMotions();
            this._updating = false;
            this._initialized = true;
            this.createRenderer();
            this.setupTextures();
            this.getRenderer().startUp(
              this._subdelegate.getGlManager().getGl()
            );

            if (this._onModelLoadCompleteCallback) {
              console.log('[LAppModel] Invoking the stored callback function.');
              this._onModelLoadCompleteCallback();
            } else {
              console.warn(
                '[LAppModel] Callback was null when trying to invoke it after loading all motions.'
              );
            }
          } else {
            console.log(
              `[LAppModel] preLoadMotionGroup: Motion count ${this._motionCount} is less than expected ${this._allMotionCount}. Not calling callback yet.`
            );
          }
        })
        .catch(fetchError => {
          console.error(
            `[LAppModel] preLoadMotionGroup: Fetch error for motion ${name} (${motionFileName}):`,
            fetchError
          );
          this._allMotionCount--;
          console.warn(
            `[LAppModel] preLoadMotionGroup: Adjusted total count after fetch error: ${this._allMotionCount}`
          );
          console.log(
            `[LAppModel] preLoadMotionGroup: Checking after error... Count: ${this._motionCount}, Total Expected: ${this._allMotionCount}`
          );

          if (this._motionCount >= this._allMotionCount) {
            console.log(
              `[LAppModel] preLoadMotionGroup: All motions loaded (or failed) for this model instance (Count: ${this._motionCount}, Expected: ${this._allMotionCount}). Calling callback.`
            );
            this._state = LoadStep.LoadTexture;
            this._motionManager.stopAllMotions();
            this._updating = false;
            this._initialized = true;
            this.createRenderer();
            this.setupTextures();
            this.getRenderer().startUp(
              this._subdelegate.getGlManager().getGl()
            );

            if (this._onModelLoadCompleteCallback) {
              console.log(
                '[LAppModel] Invoking the stored callback function after error.'
              );
              this._onModelLoadCompleteCallback();
            } else {
              console.warn(
                '[LAppModel] Callback was null when trying to invoke it after loading all motions (after error).'
              );
            }
          }
        });
    }
  }

  public releaseMotions(): void {
    this._motions.clear();
  }

  public releaseExpressions(): void {
    this._expressions.clear();
  }

  public doDraw(): void {
    if (this._model == null) return;
    const canvas = this._subdelegate.getCanvas();
    const viewport: number[] = [0, 0, canvas.width, canvas.height];
    this.getRenderer().setRenderState(
      this._subdelegate.getFrameBuffer(),
      viewport
    );
    this.getRenderer().drawModel();
  }

  public draw(matrix: CubismMatrix44): void {
    if (this._model == null) {
      return;
    }

    if (this._state == LoadStep.CompleteSetup) {
      matrix.multiplyByMatrix(this._modelMatrix);
      this.getRenderer().setMvpMatrix(matrix);
      this.doDraw();
    }
  }

  public async hasMocConsistencyFromFile() {
    CSM_ASSERT(this._modelSetting.getModelFileName().localeCompare(``));

    if (this._modelSetting.getModelFileName() != '') {
      const modelFileName = this._modelSetting.getModelFileName();
      const response = await fetch(`${this._modelHomeDir}${modelFileName}`);
      const arrayBuffer = await response.arrayBuffer();
      this._consistency = CubismMoc.hasMocConsistency(arrayBuffer);

      if (!this._consistency) {
        CubismLogInfo('Inconsistent MOC3.');
      } else {
        CubismLogInfo('Consistent MOC3.');
      }

      return this._consistency;
    } else {
      LAppPal.printMessage('Model data does not exist.');
    }
  }

  public setSubdelegate(subdelegate: LAppSubdelegate): void {
    this._subdelegate = subdelegate;
  }

  _modelSetting: ICubismModelSetting;
  _modelHomeDir: string;
  _userTimeSeconds: number;
  _eyeBlinkIds: csmVector<CubismIdHandle>;
  _lipSyncIds: csmVector<CubismIdHandle>;
  _motions: csmMap<string, ACubismMotion>;
  _expressions: csmMap<string, ACubismMotion>;
  _hitArea: csmVector<csmRect>;
  _userArea: csmVector<csmRect>;
  _idParamAngleX: CubismIdHandle;
  _idParamAngleY: CubismIdHandle;
  _idParamAngleZ: CubismIdHandle;
  _idParamEyeBallX: CubismIdHandle;
  _idParamEyeBallY: CubismIdHandle;
  _idParamBodyAngleX: CubismIdHandle;
  _state: LoadStep;
  _expressionCount: number;
  _textureCount: number;
  _motionCount: number;
  _allMotionCount: number;
  _wavFileHandler: LAppWavFileHandler;
  _consistency: boolean;
}
